/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('overstaffed','Formed from over- + staff + -ed; the adjective describes an organization with more employees than its workload requires.',C('overstaffed.s1','商业','The small branch was overstaffed on quiet Mondays, so several employees had too little work to do.','这家小分店在冷清的周一人手过多，几名员工无事可做。','The small branch was overstaffed / on quiet Mondays / so several employees / had too little work to do.','overstaffed.s1 指员工数量超过工作量所需。','员工闲置体现人手多于工作需求。','word-formation'),M('The branch was overstaffed because it had too few employees to serve the long queue.','The branch was understaffed because it had too few employees to serve the long queue.','员工不足应称 understaffed；overstaffed 表示人手过多。','confusable'),[Q(1,'Why was the branch overstaffed on Mondays?','It had more employees than the quiet workload needed.','It had too few workers for the queue.','Its employees were all on holiday.','overstaffed.s1 describes excess staffing relative to workload.'),Q(1,'Which situation is overstaffed?','A shop schedules ten clerks when two customers arrive all morning.','A clinic has one nurse for a packed ward.','A team has exactly enough workers for each shift.','Overstaffing means staffing exceeds the work demand.'),Q(1,'What is the opposite staffing problem?','understaffed','overdue','overweight','Understaffed means there are too few workers.'),Q(1,'What does -ed contribute in overstaffed?','It forms an adjective describing a state of having excess staff.','It marks a person who staffs a team.','It changes staff into a plural noun.','The compound adjective describes the resulting staffing condition.','word-formation')]);
P('overstate','From over- + state; it means to describe something as greater or more certain than it really is, and in “hard to overstate” it emphasizes exceptional importance.',[C('overstate.s1','写作','The report overstated the savings by counting a one-time grant as money the program would receive every year.','报告夸大了节省额，把一次性补助算成项目每年都会收到的钱。','The report overstated the savings / by counting a one-time grant / as money the program / would receive every year.','overstate.s1 指把数量、效果或事实说得超过实际。','把一次性收入当作年年收入会夸大节省额。'),C('overstate.s2','书面','It is hard to overstate how much the emergency clinic mattered to residents during the flood.','很难过分强调这家急诊诊所在洪灾期间对居民有多重要。','It is hard to overstate / how much the emergency clinic mattered / to residents / during the flood.','overstate.s2 常用于 it is hard to overstate，表示某事的重要性极高。','否定结构强调其重要性难以言尽。')],M('The analyst overstated the cost by reporting $900 when the verified invoice was $90.','The analyst reported the verified cost of $90.','把90美元说成900美元夸大了实际金额。','number'),[Q(1,'How did the report overstate the savings?','It treated a one-time grant as recurring yearly money.','It excluded the grant from every calculation.','It reported the exact verified amount.','overstate.s1 means to represent an amount as larger than it is.'),Q(2,'What does “hard to overstate” emphasize about the clinic?','Its importance was exceptionally great.','The clinic was unimportant.','The clinic charged too much.','This fixed expression stresses importance rather than exaggeration.'),Q(1,'Which statement overstates a result?','“The trial doubled output” when it rose only 5 percent.','“Output rose 5 percent” when records confirm that figure.','“The trial ended on Tuesday” when the log says Tuesday.','A claim larger than the verified result is overstated.'),Q(2,'What is the force of “It is hard to overstate her contribution”?','Her contribution was extremely important.','Her contribution was definitely small.','Her contribution cannot be measured in money only.','The negative construction communicates very high importance.','usage')]);
P('overt','From French overt “open, evident,” the past participle of ouvrir “to open”; it describes conduct that is visible or an aim shown without concealment.',[C('overt.s1','政治','The committee found no overt campaign activity in the building because no signs, speeches, or canvassing were visible.','委员会没有发现楼内有公开的竞选活动，因为看不到标语、演讲或拉票。','The committee found no overt campaign activity / in the building / because no signs, speeches, / or canvassing were visible.','overt.s1 指公开进行、别人能看见的行为。','标语、演讲和拉票都是可见活动。'),C('overt.s2','态度','Her overt hostility toward the proposal was clear when she called it harmful before the discussion began.','她在讨论开始前就称提案有害，公开表现出敌意。','Her overt hostility toward the proposal / was clear / when she called it harmful / before the discussion began.','overt.s2 指感情或目的明显表现出来、毫不掩饰。','她明确表达反对，没有隐藏态度。')],M('The panel described the secret, hidden vote as overt even though observers could not see that voting was taking place.','The panel described the publicly visible vote as overt.','隐蔽进行与 overt 的“公开可见”含义相反。','distinction'),[Q(1,'Why was there no overt campaign activity in the building?','No visible signs, speeches, or canvassing took place.','A secret ballot was held behind closed doors.','The committee approved a budget.','overt.s1 means openly visible.'),Q(2,'What showed her overt hostility?','She openly called the proposal harmful.','She privately agreed with it.','She said nothing about it.','overt.s2 describes an unmistakably expressed attitude.'),Q(1,'Which is overt conduct?','A public demonstration held on the main square.','A plan discussed in a sealed private message.','An unspoken thought never shown to others.','Overt action is visible or openly done.'),Q(2,'What does overt describe in “overt hostility”?','A clearly displayed feeling.','A hidden plan no one can detect.','A temporary staffing shortage.','Here overt means the hostility is not concealed.','meaning')]);
P('overtake','From over- + take, based on the idea of taking the lead; it can mean pass someone ahead, become greater than something, or suddenly affect someone.',[C('overtake.s1','交通','On the empty straight road, the driver checked for oncoming traffic before overtaking the slow tractor.','在空旷的直路上，司机先确认没有对向车辆，然后超越了缓慢行驶的拖拉机。','On the empty straight road / the driver checked for oncoming traffic / before overtaking / the slow tractor.','overtake.s1 指从后面赶上并超过车辆或人。','司机在安全确认后从后方超过拖拉机。'),C('overtake.s2','经济','Online orders overtook in-store purchases last month, becoming the larger share of the company’s sales.','上个月网购订单超过了店内购买，成为公司销售额中占比更大的部分。','Online orders overtook in-store purchases / last month / becoming the larger share / of the company’s sales.','overtake.s2 指数量、速度或成绩超过另一事物。','网购订单的份额变得更大。'),C('overtake.s3','书面','A wave of relief overtook him when the doctor said the scan showed no serious problem.','医生说扫描没有发现严重问题时，一阵宽慰突然涌上他的心头。','A wave of relief overtook him / when the doctor said / the scan showed / no serious problem.','overtake.s3 指某种强烈感受突然降临并影响某人。','宽慰感突然袭来。')],M('She overtook the truck on a blind bend although she could not see whether traffic was approaching.','She waited until the road was clear before overtaking the truck.','在盲弯看不到对向车辆时超车是不安全的错误做法。','context'),[Q(1,'What safety check did the driver make before overtaking?','He checked for oncoming traffic.','He turned off the headlights.','He moved onto a blind bend.','overtake.s1 is passing a vehicle from behind.'),Q(2,'What happened to online orders?','They became a larger share than in-store purchases.','They fell to zero.','They remained smaller than in-store purchases.','overtake.s2 means become greater than another quantity.'),Q(3,'What overtook him after the doctor’s news?','A wave of relief.','A tractor on the road.','A rise in online orders.','overtake.s3 describes a feeling suddenly affecting someone.'),Q(1,'Which use means “pass a vehicle ahead”?','A car overtook a slow bus on a clear road.','The storm overtook the coastal town.','Sales overtook last year’s total.','The first sentence describes passing a vehicle.','distinction')]);
P('overtax','From over- + tax; it means to demand too much tax or to strain someone’s strength, patience, or resources beyond a reasonable limit.',C('overtax.s1','通用','The extra night shift began to overtax the nurses, so the hospital hired temporary staff and revised the rota.','额外夜班开始让护士们不堪重负，因此医院雇用临时人员并调整排班。','The extra night shift / began to overtax the nurses / so the hospital hired temporary staff / and revised the rota.','overtax.s1 指征收过重税负，或使人的能力、耐心等承受过度压力。','夜班过多让护士难以承受。','meaning'),M('The repeated night shifts rested the nurses and left them with plenty of energy, but the manager said the schedule overtaxed them.','The repeated night shifts overtaxed the nurses and left them exhausted.','overtax 表示负担过重，不适用于轻松且不费力的安排。','distinction'),[Q(1,'What did the extra night shift do to the nurses?','It strained them beyond a reasonable limit.','It reduced their workload.','It gave them a longer holiday.','overtax.s1 includes placing excessive demands on someone.'),Q(1,'Which situation could overtax a small business?','A tax bill so high that it cannot meet basic operating costs.','A modest fee it can easily pay.','A refund that covers its expenses.','Overtax can mean impose excessive tax.'),Q(1,'Which sentence uses overtax figuratively?','The nonstop deadlines overtaxed the editor’s concentration.','The editor took a short break after lunch.','The editor checked a schedule once.','The first sentence describes excessive strain on capacity.'),Q(1,'What does the prefix over- signal in overtax?','An excessive amount or degree.','A location beneath something.','A completed action only.','Here over- indicates excessive demand.','word-formation')]);
P('overthrow','From over- + throw; it means forcibly remove a leader or government, or the act of doing so.',[C('overthrow.s1','政治','A coalition of generals tried to overthrow the elected government, but the parliament remained in control.','一批将领试图推翻民选政府，但议会仍掌握着政权。','A coalition of generals tried / to overthrow the elected government / but the parliament / remained in control.','overthrow.s1 作动词，指用武力推翻领导人、政府或制度。','将领企图以武力取代现有政府。'),C('overthrow.s2','政治','The overthrow of the monarchy followed months of protests and a final vote by the assembly.','经过数月抗议和议会的最后表决，君主制被推翻了。','The overthrow of the monarchy / followed months of protests / and a final vote / by the assembly.','overthrow.s2 作名词，指推翻政府或领导人的行为。','名词指君主制被推翻这一行为。')],M('The peaceful election was an overthrow because the incumbent kept office and no leader or system was removed.','The armed removal of the incumbent government was an overthrow.','保留现有政府的和平选举不是推翻政权。','meaning'),[Q(1,'What did the generals try to do?','Remove the elected government by force.','Organize its next public meeting.','Increase the cabinet’s staff.','overthrow.s1 is the verb for forcibly removing a government.'),Q(2,'What followed protests and an assembly vote?','The overthrow of the monarchy.','A musical overture.','An overtime payment.','overthrow.s2 is the noun for the act of removing a ruler.'),Q(1,'Which event is an overthrow?','A military group forcibly removes a ruling government.','A candidate loses a routine election and leaves office.','A cabinet changes its meeting time.','Overthrow entails removing a ruler or system, often by force.'),Q(2,'In “the overthrow of the regime,” what part of speech is overthrow?','A noun naming the act of removal.','A verb taking an object.','An adjective meaning hidden.','The phrase uses overthrow as a noun.','grammar')]);
P('overtime','From over- + time; it can mean hours worked beyond the usual schedule, extra pay for those hours, or an extra period in a tied game.',[C('overtime.s1','工作','Because the shipment arrived late, the warehouse crew worked overtime to finish loading before dawn.','由于货物到得晚，仓库人员加班装货，赶在黎明前完成。','Because the shipment arrived late / the warehouse crew worked overtime / to finish loading / before dawn.','overtime.s1 指正常工时之外的工作时间。','团队延长工作时间完成装货。'),C('overtime.s2','工作','Her payslip listed overtime separately, showing the extra amount earned for hours beyond her regular shift.','她的工资单单独列出加班费，显示了正常班次之外工作所得的额外报酬。','Her payslip listed overtime separately / showing the extra amount / earned for hours / beyond her regular shift.','overtime.s2 指超时工作所得的额外报酬。','工资单把加班所得单列出来。'),C('overtime.s3','体育','The tied hockey match went into overtime, and the winning goal was scored in the extra period.','这场打平的冰球比赛进入加时赛，制胜进球在加时阶段打进。','The tied hockey match / went into overtime / and the winning goal / was scored in the extra period.','overtime.s3 指比分平局后追加的比赛时段。','平局导致比赛增加时段。')],M('The hockey match ended at regulation time with the score tied, but the announcer said the teams were playing overtime even though no extra period began.','The tied hockey match went into overtime when the officials started an extra period.','如果没有追加比赛时段，就没有开始加时赛。','context'),[Q(1,'Why did the warehouse crew work overtime?','A late shipment had to be loaded before dawn.','The game needed a deciding goal.','The payslip was being printed.','overtime.s1 refers to extra hours worked.'),Q(2,'What did the payslip show?','Extra pay earned beyond the regular shift.','The number of hours in a tied game.','The employee’s regular lunch break.','overtime.s2 means additional pay for extra work.'),Q(3,'Why did the hockey match go into overtime?','The score was tied at the end of normal play.','The warehouse finished early.','A player requested a longer shift.','overtime.s3 is an extra period in a tied game.'),Q(1,'Which use refers to money?','She received overtime for staying three extra hours.','She worked overtime on Friday.','The match went into overtime.','The first sentence uses overtime for extra pay.','distinction')]);
P('overtire','Formed from over- + tire; it means make a person or animal so tired that continuing may be unsafe or ineffective.',C('overtire.s1','健康','The trainer shortened the puppy’s walk to avoid overtiring it before its first agility class.','训练员缩短了小狗的散步时间，以免它在第一次敏捷训练课前过度疲劳。','The trainer shortened the puppy’s walk / to avoid overtiring it / before its first / agility class.','overtire.s1 指使人或动物疲劳过度，难以安全继续。','减少运动时间以免小狗过劳。','word-formation'),M('The trainer overtired the puppy by stopping the walk early and letting it nap before class.','The trainer overtired the puppy by making it run for hours without a rest.','提前休息不会使小狗过劳；长时间不停奔跑才可能造成过度疲劳。','meaning'),[Q(1,'Why did the trainer shorten the puppy’s walk?','To keep it from becoming too tired before class.','To make it miss its first meal.','To train it to carry a pack.','overtire.s1 means tire someone or an animal excessively.'),Q(1,'Which plan could overtire a hiker?','Forcing a long climb without water or rest.','Taking breaks and stopping before exhaustion.','Walking a short, easy trail.','The first plan places excessive strain on the hiker.'),Q(1,'What does overtire mean?','Make too tired to continue safely.','Give extra pay for a long shift.','Change a legal ruling.','The verb describes excessive fatigue.'),Q(1,'What does over- add to tire in overtire?','Excessively.','Again.','In the opposite direction.','The prefix signals too much tiredness.','word-formation')]);
P('overtone','From over- + tone; the word can mean an implied feeling or meaning, or a higher partial tone sounding with a musical fundamental.',[C('overtone.s1','通用','The editor removed the sarcastic overtone from the note by replacing “as usual” with a neutral phrase.','编辑把“像往常一样”换成中性说法，消除了便条中的讽刺意味。','The editor removed the sarcastic overtone / from the note / by replacing “as usual” / with a neutral phrase.','overtone.s1 指话语中暗示但未直接说出的感情色彩或含义。','原措辞带有未明说的讽刺意味。'),C('overtone.s2','音乐','A flute’s clear overtone blended with the fundamental note and gave the sustained pitch its bright quality.','长笛清亮的泛音与基音融合，使持续的音高带有明亮音色。','A flute’s clear overtone / blended with the fundamental note / and gave the sustained pitch / its bright quality.','overtone.s2 指与基音一同发声的较高频率音。','泛音与基音共同构成音色。')],M('The note had no implied attitude at all, yet the editor said its overtone was sarcastic because it contained an explicit direct insult.','The note carried a sarcastic overtone because its polite wording indirectly mocked the recipient.','overtone 可指暗示的语气；直接明说的侮辱不是未明说的暗示。','distinction'),[Q(1,'What did the editor remove from the note?','An indirectly sarcastic tone.','A higher flute frequency.','A paragraph about work hours.','overtone.s1 is an implied emotional shade.'),Q(2,'What blended with the flute’s fundamental note?','A higher partial sound.','A sarcastic phrase.','The orchestra’s opening overture.','overtone.s2 is a higher frequency sounding with the fundamental.'),Q(1,'Which sentence has a threatening overtone?','“You may want to leave now,” said with a cold smile.','“The door is open,” said while giving neutral directions.','“The room is blue,” said as a literal description.','The first words suggest an unstated warning.'),Q(2,'Which use is musical?','The overtone enriched the instrument’s sustained pitch.','The apology had a resentful overtone.','The negotiator made an overture.','The first sentence describes a partial tone in music.','distinction')]);
P('overture','From French ouverture “opening,” from ouvrir “to open”; it names an orchestral opening piece or an approach intended to begin talks or a relationship.',[C('overture.s1','音乐','The orchestra played the overture before the curtain rose on the opera.','歌剧开幕前，管弦乐团演奏了序曲。','The orchestra played the overture / before the curtain rose / on the opera.','overture.s1 指歌剧或类似作品开场时演奏的管弦乐曲。','序曲在剧情开场前演奏。'),C('overture.s2','社交','The union made an overture to management by requesting an informal meeting to discuss safer shifts.','工会主动向管理层提出会面，要求非正式讨论更安全的轮班安排。','The union made an overture to management / by requesting an informal meeting / to discuss safer shifts.','overture.s2 指为开始谈判、友谊或合作而作出的主动表示。','工会主动提出会面以开启协商。')],M('The union rejected every request to meet but called its silence an overture to begin negotiations.','The union proposed an informal meeting as an overture to begin negotiations.','没有提出任何接触或邀请，不能算作开启谈判的表示。','meaning'),[Q(1,'When did the orchestra play the overture?','Before the opera began on stage.','After the final curtain and applause.','During the union’s meeting with management.','overture.s1 is an opening orchestral piece.'),Q(2,'What was the union’s overture?','A request for an informal meeting.','A song played before an opera.','A refusal to communicate.','overture.s2 is an approach to start discussion.'),Q(1,'Which work is an overture?','An orchestral introduction before an opera.','The final song after the story ends.','A printed safety agreement.','The opening piece is the overture.'),Q(2,'Which action is an overture to friendship?','Inviting a neighbor for coffee to start talking.','Ignoring all messages.','Ending an existing conversation abruptly.','An overture is an opening gesture.','meaning')]);
P('overturn','From over- + turn; it means turn something onto its side or upside down, or officially reverse a ruling or decision.',[C('overturn.s1','通用','A gust of wind overturned the garden chair and left it lying on its side beside the path.','一阵风把花园椅吹翻，使它侧倒在小路旁。','A gust of wind / overturned the garden chair / and left it lying / on its side beside the path.','overturn.s1 指使物体翻倒或倾覆。','椅子被风吹倒到一侧。'),C('overturn.s2','法律','The appeals court overturned the ruling after finding that the trial judge had applied the wrong legal test.','上诉法院发现审判法官适用了错误的法律标准后，撤销了该裁决。','The appeals court overturned the ruling / after finding / that the trial judge / had applied the wrong legal test.','overturn.s2 指正式认定裁决或决定有误并将其撤销。','法院正式取消了原裁决。')],M('The appeals court upheld the ruling without changing it, so the newspaper reported that the court overturned it.','The appeals court overturned the ruling and replaced it with a new decision.','维持裁决与撤销裁决相反。','confusable'),[Q(1,'What happened to the garden chair?','It fell onto its side.','It was repaired in the courtroom.','It remained upright during the wind.','overturn.s1 means turn something onto its side.'),Q(2,'Why did the appeals court overturn the ruling?','The trial judge used the wrong legal test.','The chair had blown into the path.','The ruling had never been issued.','overturn.s2 is the formal reversal of a decision.'),Q(1,'Which event is a physical overturning?','A cart tips onto its side.','A judge cancels a ruling.','A council withdraws a policy.','The cart is physically turned onto its side.'),Q(2,'Which is a legal overturning?','A higher court reverses a lower court’s decision.','A gust flips a garden chair.','A vase falls from a shelf.','A court can officially reverse a ruling.','distinction')]);
P('overuse','From over- + use; as a verb it means use something so much that it becomes weakened or annoying, and as a noun it names excessive use.',[C('overuse.s1','语言','The essay overused “very,” so the editor replaced several instances with more precise descriptions.','这篇文章过度使用“非常”，编辑便把其中几处换成更准确的描述。','The essay overused “very” / so the editor replaced / several instances / with more precise descriptions.','overuse.s1 作动词，指过频使用某物，使其效果变弱或令人厌烦。','同一副词重复太多，编辑减少其出现次数。'),C('overuse.s2','健康','The physiotherapist explained that overuse of the shoulder muscle had caused the pain, not a single sudden injury.','理疗师解释说，疼痛由肩部肌肉使用过度造成，并非一次突然受伤。','The physiotherapist explained / that overuse of the shoulder muscle / had caused the pain / not a single sudden injury.','overuse.s2 作名词，指超过合理限度的使用。','持续过度使用造成了疼痛。')],M('The writer overused the word “very” by using it only once in a hundred-page report.','The writer overused “very” by repeating it in nearly every paragraph.','偶尔使用一次不构成过度使用；反复到令人厌烦才是 overuse。','number'),[Q(1,'What did the editor change in the essay?','Repeated uses of “very.”','The shoulder muscle itself.','The essay’s publication date.','overuse.s1 refers to using a word too often.'),Q(2,'What caused the shoulder pain in the explanation?','Excessive use of the muscle over time.','One sudden injury only.','A repeated adjective in an essay.','overuse.s2 is the noun for excessive use.'),Q(1,'Which sentence uses overuse as a verb?','He overused the same joke until no one laughed.','The overuse of the machine damaged its seal.','The seal was already worn.','In the first sentence, overused is an action verb.'),Q(2,'Which phrase uses overuse as a noun?','overuse of antibiotics','to overuse a phrase','overused equipment','The phrase names excessive use as a thing or condition.','grammar')]);
P('overview','From over- + view; a noun for a general summary that gives the main points without every detail.',C('overview.s1','教育','The first page gives an overview of the course, then later sections explain each unit and assignment in detail.','第一页概述了课程内容，后面的部分再详细说明各单元和作业。','The first page gives an overview / of the course / then later sections explain / each unit and assignment in detail.','overview.s1 指概括主要内容的总体说明。','第一页先提供总览，之后再展开细节。','word-formation'),M('The course overview listed every sentence of every reading in full but gave no general summary of the course.','The course overview briefly described its goals, units, and main assignments.','逐字罗列细节而不概括重点，不符合 overview 的作用。','meaning'),[Q(1,'What does the first page provide?','A general summary of the course.','Every reading in full.','Only the instructor’s phone number.','overview.s1 is a broad description of the main points.'),Q(1,'Which item is an overview?','A one-page outline of a report’s purpose and sections.','A verbatim copy of every page.','A list containing only page numbers.','An overview summarizes rather than reproduces all details.'),Q(1,'What should an overview usually leave for later sections?','Detailed explanations of individual units.','The main topic entirely.','The title of the report.','A summary gives the outline; later sections provide detail.'),Q(1,'How is overview formed?','over + view','owl + view','overt + -ly','It combines over and view to name a broad look at a topic.','word-formation')]);
P('overweight','From over- + weight; it describes a person or object whose weight is above a relevant or healthy limit.',C('overweight.s1','健康','The doctor discussed the patient’s health risks privately and offered support without reducing the person to a number on a scale.','医生私下讨论了患者的健康风险，并给予支持，没有把这个人简化为秤上的数字。','The doctor discussed the patient’s health risks / privately / and offered support / without reducing the person to a number on a scale.','overweight.s1 指体重高于相关健康标准；描述人时应避免污名化。','例句以尊重方式讨论体重相关健康问题。','register'),M('The report called a healthy-weight patient overweight even though the clinician’s measurements placed the patient within the recommended range.','The report described the patient’s measured weight accurately and discussed health context with care.','是否超重需依据恰当的健康标准，不能把处于推荐范围的人随意标为超重。','usage'),[Q(1,'What did the doctor discuss with care?','Health risks related to the patient’s weight.','The patient’s value as a person.','The weather at the clinic.','overweight.s1 refers to weight above a relevant health limit.'),Q(1,'Which package is overweight for a 20-kilogram limit?','One weighing 24 kilograms.','One weighing 18 kilograms.','One weighing exactly 20 kilograms.','Overweight means exceeding the stated limit.'),Q(1,'Which description is more respectful in a health discussion?','Discuss measured weight and health context privately.','Use a person’s weight as an insult.','Assume a diagnosis without measurements.','The context recommends precise and respectful language.'),Q(1,'What does the prefix over- indicate in overweight?','Above or beyond a limit.','Below the usual level.','A repeated action.','Over- signals exceeding the relevant weight limit.','word-formation')]);
P('overwhelm','From Old English oferhwelmian, over- + a verb related to welm “surge”; it means give someone more than they can manage, or defeat/cover completely.',[C('overwhelm.s1','情感','The simultaneous deadlines overwhelmed the new coordinator, who asked her manager to help prioritize the work.','多个截止日期同时压来，让新协调员应接不暇；她请经理帮忙安排优先级。','The simultaneous deadlines / overwhelmed the new coordinator / who asked her manager / to help prioritize the work.','overwhelm.s1 指工作、信息或情绪过多，使人无法应付。','多个期限一起到来使她难以处理。'),C('overwhelm.s2','自然','The spring flood overwhelmed the low riverbank and covered the footpath with water.','春季洪水漫过低矮的河岸，把步道淹没了。','The spring flood / overwhelmed the low riverbank / and covered the footpath / with water.','overwhelm.s2 指彻底击败，或完全覆盖某物。','洪水漫过河岸并覆盖步道。')],M('The short, quiet briefing overwhelmed the experienced team because it contained only one clear instruction.','The dense briefing overwhelmed the team with dozens of urgent instructions and no time to act.','信息量很少且清晰的简报通常不足以使团队无法应付。','distinction'),[Q(1,'Why did the coordinator feel overwhelmed?','Several deadlines arrived at the same time.','She had no assignments at all.','The river covered a path.','overwhelm.s1 describes demands exceeding someone’s capacity.'),Q(2,'What did the spring flood do?','It covered the low bank and footpath.','It helped the coordinator rank tasks.','It reduced the water level.','overwhelm.s2 means cover or overpower completely.'),Q(1,'Which situation could overwhelm a student?','Three major projects due on the same day.','One small task due next month.','A free afternoon with no work.','Too many demands can overwhelm someone.'),Q(2,'Which use of overwhelm is physical?','Floodwater overwhelmed the barrier.','The messages overwhelmed the clerk.','A feeling of relief overwhelmed him.','The first sentence describes water physically covering a barrier.','distinction')]);
P('overwhelming','From overwhelm + -ing; it describes a force or advantage that cannot be resisted, or an amount/feeling too strong to manage.',[C('overwhelming.s1','通用','The candidate won an overwhelming victory, receiving nearly four times as many votes as the runner-up.','这位候选人以压倒性优势获胜，得票数接近第二名的四倍。','The candidate won an overwhelming victory / receiving nearly four times as many votes / as the runner-up.','overwhelming.s1 指强大到对方几乎无法抵抗的。','巨大的票数差距体现压倒性优势。'),C('overwhelming.s2','情感','The family found the first week after the move overwhelming, with paperwork, boxes, and new routines all demanding attention.','搬家后的第一周让全家应接不暇，文件、纸箱和新作息都需要处理。','The family found the first week after the move overwhelming / with paperwork, boxes, / and new routines / all demanding attention.','overwhelming.s2 指感情或事务量大到难以应付。','许多事情同时要处理，令人难以招架。')],M('The result was called an overwhelming victory even though the winner received fewer votes than every opponent.','The result was called an overwhelming victory because the winner received far more votes than the runner-up.','微弱或落后的结果不能称为压倒性胜利。','meaning'),[Q(1,'Why was the candidate’s victory overwhelming?','The vote total was nearly four times the runner-up’s.','The candidate lost by one vote.','The election was postponed.','overwhelming.s1 describes a victory too large for the other side to resist.'),Q(2,'What made the first week overwhelming for the family?','Many tasks and new routines demanded attention at once.','They had no boxes or paperwork.','The move had been canceled.','overwhelming.s2 refers to an unmanageable amount of demands.'),Q(1,'Which result is an overwhelming victory?','A team wins 8–0 in a one-sided final.','Two teams tie 1–1.','A team loses 0–8.','A decisive margin can be described as overwhelming.'),Q(2,'Which situation feels overwhelming?','A person receives dozens of urgent forms to finish by morning.','A person completes one short form with a week to spare.','A person has no pending tasks.','A very large amount of work can be overwhelming.','meaning')]);
P('overwhelmingly','From overwhelming + -ly; the adverb means to such a great extent that opposition, doubt, or alternatives are very small.',C('overwhelmingly.s1','通用','The residents voted overwhelmingly for the safer crossing, with only three ballots against the proposal.','居民以压倒性多数投票支持更安全的过街设施，只有三票反对。','The residents voted overwhelmingly / for the safer crossing / with only three ballots / against the proposal.','overwhelmingly.s1 表示程度极大，反对或疑问很少。','支持票远多于反对票。','word-formation'),M('The proposal passed overwhelmingly even though 98 percent of voters rejected it and only two people supported it.','The proposal was overwhelmingly rejected because nearly all voters opposed it.','压倒性结果的方向必须与绝大多数票的实际倾向一致。','number'),[Q(1,'How many ballots opposed the crossing proposal?','Three.','Nearly all ballots.','None of the residents voted.','overwhelmingly.s1 describes the large margin in favor.'),Q(1,'Which statement shows that a motion passed overwhelmingly?','Ninety-six members voted yes and four voted no.','Fifty members voted yes and fifty voted no.','Four voted yes and ninety-six voted no.','The first result has a very large majority.'),Q(1,'What does overwhelmingly add to “the team won”?','It emphasizes a very large margin.','It says the team tied.','It states the win was secret.','The adverb marks an exceptionally strong result.'),Q(1,'How is overwhelmingly formed?','overwhelming + -ly','overwhelm + plural -s','over + noun time','-ly forms an adverb from overwhelming.','word-formation')]);
P('overwinter','From over- + winter; in biology and ecology it means survive through the winter, often in a particular place or state.',C('overwinter.s1','自然','Adult monarch butterflies overwinter in sheltered forests where temperatures remain cool but rarely freeze.','成年帝王蝶在温度凉爽但很少结冰的避风林地越冬。','Adult monarch butterflies overwinter / in sheltered forests / where temperatures remain cool / but rarely freeze.','overwinter.s1 指在冬季存活下来。','蝴蝶在避风林地度过冬天。','word-formation'),M('The seedlings overwintered in the greenhouse, but every one of them died before winter began.','The seedlings overwintered in the greenhouse and survived until spring.','若入冬前全部死亡，就没有存活过整个冬季。','meaning'),[Q(1,'Where do the butterflies overwinter?','In sheltered forests.','On a hot beach during summer.','In a city office.','overwinter.s1 refers to surviving through winter in a place.'),Q(1,'Which animal may overwinter in a burrow?','A ground squirrel that remains there through cold months.','A migrating bird that leaves before winter.','A fish that lives only in summer ponds.','The squirrel survives through winter in the burrow.'),Q(1,'Which sentence uses overwinter correctly?','The bulbs overwintered underground and sprouted in April.','The bulbs overwintered in May after the spring bloom ended.','The bulbs overwintered by flowering for one afternoon.','The first example describes survival through winter.'),Q(1,'What does over- mean in overwinter?','Through or across the winter season.','Above the snow only.','Again after a brief pause.','The compound verb means pass through winter.','word-formation')]);
P('overwork','From over- + work; as a noun it means too much work or working for too long, often causing strain or exhaustion.',C('overwork.s1','职业','The staff survey linked persistent overwork to fatigue and asked managers to redistribute the evening workload.','员工调查把长期过度工作与疲劳联系起来，并要求经理重新分配晚间工作量。','The staff survey linked persistent overwork / to fatigue / and asked managers / to redistribute the evening workload.','overwork.s1 指工作量过多或工作时间过长。','长期工作过度与疲劳相关。'),M('The report called a paid day off overwork even though the employee had done no work that day.','The report identified repeated fourteen-hour shifts with no rest days as overwork.','完全没有工作不能称为工作过度。','meaning'),[Q(1,'What did the survey connect with fatigue?','Persistent excessive work.','A paid day off.','A shorter evening shift.','overwork.s1 means too much work or overly long hours.'),Q(1,'Which schedule is most clearly overwork?','Fourteen-hour shifts every day with no rest.','One normal shift followed by a weekend off.','A short task completed before lunch.','The first schedule creates excessive work and hours.'),Q(1,'In this entry, what part of speech is overwork?','A noun.','A past-tense verb.','An adjective describing weight.','The example uses overwork as a noun.'),Q(1,'Which health effect is associated with overwork in the context?','Fatigue.','A higher vote total.','A musical overtone.','The example explicitly links too much work with fatigue.','context')]);
P('overwrought','From over- + wrought, an older past participle of work; it describes someone excessively anxious or excited, or writing/design made strained by too much detail.',[C('overwrought.s1','心理','Before the hearing, he sounded overwrought and had to pause several times to regain his composure.','听证会前，他显得焦虑过度，几次停下来才恢复镇定。','Before the hearing / he sounded overwrought / and had to pause several times / to regain his composure.','overwrought.s1 指焦虑或激动过度，以至不能冷静思考。','他需要停顿来恢复镇定。'),C('overwrought.s2','文学','The reviewer found the novel’s final paragraph overwrought, with so many metaphors that the simple farewell became hard to follow.','评论家觉得小说末段过于雕琢，堆砌了太多隐喻，反而让简单的告别难以理解。','The reviewer found the novel’s final paragraph overwrought / with so many metaphors / that the simple farewell / became hard to follow.','overwrought.s2 指文字或设计过于复杂、刻意，显得用力过猛。','过多隐喻使结尾显得过度雕琢。')],M('The calm witness was described as overwrought even though she spoke evenly, felt no anxiety, and answered without distress.','The visibly anxious witness who could not speak calmly was described as overwrought.','overwrought 的情绪义要求焦虑或兴奋过度；平静状态不符合。','distinction'),[Q(1,'How did he sound before the hearing?','Excessively anxious and unable to stay composed.','Completely relaxed and cheerful.','Angry at the weather only.','overwrought.s1 describes excessive anxiety or excitement.'),Q(2,'Why did the reviewer call the paragraph overwrought?','Too many metaphors made the farewell hard to follow.','It contained no imagery at all.','It was a short, clear factual note.','overwrought.s2 describes writing strained by excessive detail.'),Q(1,'Which person seems overwrought?','Someone so anxious they must stop to breathe before speaking.','Someone calm and untroubled throughout the meeting.','Someone quietly reading a short note.','The first person is too distressed to think calmly.'),Q(2,'Which passage is overwrought?','A simple apology buried under several strained metaphors.','A clear two-sentence apology.','A plain date and address.','Excessive ornament makes the writing overwrought.','distinction')]);
P('ovum','From Latin ovum “egg”; its plural is ova.',C('ovum.s1','科学','After fertilization, the ovum begins dividing as it develops into an embryo.','受精后，卵细胞开始分裂并发育成胚胎。','After fertilization / the ovum begins dividing / as it develops / into an embryo.','ovum.s1 指雌性生殖细胞，即卵细胞。','句中卵细胞受精后开始发育。','word-formation'),M('The diagram labeled a mature male sperm cell as an ovum.','The diagram labeled the female egg cell as an ovum.','ovum 指雌性卵细胞，不是精子细胞。','meaning'),[Q(1,'What happens to the ovum after fertilization?','It begins dividing as it develops.','It becomes a mature sperm cell.','It stops all cellular activity.','ovum.s1 is a female egg cell.'),Q(1,'Which cell is an ovum?','A female reproductive egg cell.','A red blood cell carrying oxygen.','A male gamete called a sperm cell.','Ovum refers to the female egg cell.'),Q(1,'What is the usual plural of ovum?','ova','ovumses','ovumies','The Latin plural form is ova.','word-formation'),Q(1,'Which scientific sentence uses ovum correctly?','The ovum was examined before fertilization.','The ovum pumped blood through the heart.','The ovum was a shellfish on the beach.','The term names the female egg cell.','meaning')]);
P('owe','From Old English āgan “to own, possess”; it developed senses of being obligated to pay, being indebted for a good result, or needing to give an explanation or apology.',[C('owe.s1','金融','I still owe the library two dollars for the damaged book, and I will pay the fee this afternoon.','我还欠图书馆两美元的书籍损坏费，今天下午会缴清。','I still owe the library two dollars / for the damaged book / and I will pay / the fee this afternoon.','owe.s1 指欠某人钱或必须归还某物。','句中明确有未偿还的两美元。'),C('owe.s2','通用','The team owes its recovery to the mechanic, whose careful repair let the engine run again.','球队的复苏多亏了那位技师；他细致的维修让引擎重新运转。','The team owes its recovery to the mechanic / whose careful repair / let the engine / run again.','owe.s2 指某种好结果归功于某人或某事。','技师的维修促成了复苏。'),C('owe.s3','社交','After missing the meeting without notice, I owe Maya an apology and a clear explanation.','我没有通知就缺席了会议，因此应该向玛雅道歉并作出明确解释。','After missing the meeting without notice / I owe Maya / an apology and / a clear explanation.','owe.s3 指觉得有必要向某人解释或道歉。','缺席后应给玛雅一个解释和道歉。')],M('I owe the bank nothing because I borrowed money and have not repaid any of it.','I owe the bank money because I borrowed funds and have not repaid them.','借款未还意味着仍有债务，不能说什么都不欠。','meaning'),[Q(1,'How much does the speaker owe the library?','Two dollars.','A damaged book with no fee.','A repair service.','owe.s1 is a debt that must be paid.'),Q(2,'What does the team owe its recovery to?','The mechanic’s careful repair.','The library’s late fee.','A missed meeting.','owe.s2 means be grateful to a cause or person for a result.'),Q(3,'What does the speaker owe Maya?','An apology and an explanation.','Two dollars for a book.','A repaired engine.','owe.s3 concerns an expected apology or explanation.'),Q(1,'Which sentence uses owe for a debt?','I owe the landlord next month’s rent.','I owe my success to my coach.','I owe you an apology.','The first sentence refers to money due.','distinction')]);
P('owed','From the past participle of owe; as an adjective it describes an amount that still has to be paid.',C('owed.s1','金融','The invoice showed the amount owed after the customer’s deposit had been subtracted.','扣除客户的定金后，发票列出了仍需支付的金额。','The invoice showed the amount owed / after the customer’s deposit / had been subtracted.','owed.s1 指尚未支付、仍欠着的款项。','定金扣除后仍有余额未付。','word-formation'),M('The receipt marked the fully paid balance as owed even though the account showed zero due.','The receipt marked the remaining unpaid balance as owed.','余额已清零就不再是欠款。','distinction'),[Q(1,'What did the invoice show as owed?','The balance remaining after the deposit.','The deposit that had already been paid.','A refund already sent to the customer.','owed.s1 is the amount still due.'),Q(1,'Which amount is owed?','A bill that remains unpaid.','A bill paid in full last week.','A credit already returned.','An owed amount still has to be paid.'),Q(1,'What does owed mean in “the money owed”?','Still to be paid.','Already refunded.','Expected to be borrowed next year.','The adjective describes an unpaid debt.'),Q(1,'Which form is owed related to?','owe','owl','overturn','Owed is the past form of owe.','word-formation')]);
P('owing','From owe + -ing; as an adjective it means still due or unpaid.',C('owing.s1','金融','The account lists one owing balance because the final installment has not yet arrived.','账户列有一笔未结清余额，因为最后一期款项尚未到账。','The account lists one owing balance / because the final installment / has not yet arrived.','owing.s1 指仍欠着、尚待支付的金额。','最后一期未付，因此余额仍未结清。','word-formation'),M('The account described the final installment as owing after it had already been paid and confirmed.','The account described the final installment as paid after it had been received.','已经支付并确认的款项不再是 owing。','distinction'),[Q(1,'Why was a balance still owing?','The final installment had not arrived.','Every installment had been paid.','The account had been closed with zero balance.','owing.s1 means still due or unpaid.'),Q(1,'Which phrase uses owing correctly?','the amount still owing on the loan','the amount owing after the loan was fully repaid','the owing refund already delivered','Owing describes an unpaid amount.'),Q(1,'What does owing mean in a bill notice?','Still to be paid.','Already canceled.','Paid twice and returned.','The adjective identifies a due balance.'),Q(1,'What is the base verb in owing?','owe','own','owl','Owing is formed from the verb owe.','word-formation')]);
P('owl','From Old English ūle; it names a nocturnal bird and informally a person who likes staying awake late at night.',[C('owl.s1','动物','At dusk, an owl perched silently on the fence and watched for mice in the field.','黄昏时，一只猫头鹰静静地停在篱笆上，观察田里的老鼠。','At dusk / an owl perched silently / on the fence / and watched for mice in the field.','owl.s1 指一种常在夜间捕食、眼睛大的鸟。','鸟在黄昏守候猎物。'),C('owl.s2','口语','As a night owl, Ben does his best reading after midnight and sleeps later on weekends.','本是个夜猫子，午夜后读书效率最高，周末会晚些起床。','As a night owl / Ben does his best reading / after midnight / and sleeps later on weekends.','owl.s2 口语中指喜欢晚睡的人。','夜里更有精神是 night owl 的特点。')],M('Ben is a night owl because he goes to bed at sunset and wakes before dawn every day.','Ben is a night owl because he prefers staying awake late at night.','日落就寝、黎明前起床与喜欢熬夜相反。','distinction'),[Q(1,'What was the owl doing at dusk?','Watching for mice from the fence.','Reading after midnight.','Building a nest in a library.','owl.s1 is the nocturnal bird.'),Q(2,'Why is Ben called a night owl?','He reads best after midnight.','He wakes before dawn and sleeps at sunset.','He studies birds for work.','owl.s2 is a person who likes staying up late.'),Q(1,'Which animal is an owl?','A large-eyed bird that often hunts at night.','A small shellfish with a hinged shell.','A male farm animal used to pull a plow.','The first description matches an owl.'),Q(2,'Which person is a night owl?','Someone who regularly stays awake late and sleeps in.','Someone who always sleeps at 8 p.m.','Someone who works only outdoors.','Night owl describes a late-night preference.','meaning')]);
P('own','From Old English āgen, “possessed, belonging to oneself,” related to āgan “possess”; it functions as a determiner, pronoun, or verb meaning possess or admit.',[C('own.s1','通用','Nora repaired her own bicycle instead of borrowing one from her neighbor.','诺拉修好了自己的自行车，没有向邻居借车。','Nora repaired her own bicycle / instead of borrowing one / from her neighbor.','own.s1 作限定词，表示某物属于特定的人。','own 放在 bicycle 前，强调车属于诺拉。'),C('own.s2','通用','Their garden is small, but they are proud of it because it is their own.','他们的花园虽小，却为它感到自豪，因为那是他们自己的。','Their garden is small / but they are proud of it / because it is their own.','own.s2 作代词，常接在物主限定词后指“自己的东西”。','their own 代指属于他们的花园。'),C('own.s3','法律','The cooperative owns the workshop building and rents its tools to local makers.','这家合作社拥有作坊建筑，并把工具出租给当地手工艺者。','The cooperative owns the workshop building / and rents its tools / to local makers.','own.s3 作动词，指在法律上拥有某物。','合作社对建筑和工具拥有所有权。'),C('own.s4','口语','When asked who had broken the seal, Liam owned his mistake and offered to replace it.','被问到是谁弄坏封条时，利亚姆承认了错误，并提出更换。','When asked who had broken the seal / Liam owned his mistake / and offered / to replace it.','own.s4 常见于 own a mistake/own up，表示承认过错。','他坦承自己做错了事。')],M('Liam owned his mistake by denying he had touched the seal and blaming an absent colleague.','Liam owned his mistake by admitting he had broken the seal and offering to fix it.','own a mistake 表示承认过错，否认责任与此相反。','meaning'),[Q(1,'Whose bicycle did Nora repair?','Her own bicycle.','Her neighbor’s bicycle.','A bicycle she rented from the cooperative.','own.s1 marks something as belonging to Nora.'),Q(2,'What does “their own” refer to?','The garden that belongs to them.','A borrowed tool.','A repair shop they do not own.','own.s2 replaces the noun after a possessive.'),Q(3,'What does the cooperative own?','The workshop building and its tools.','Only the rented land next door.','Nora’s bicycle.','own.s3 means legally possess.'),Q(4,'How did Liam own his mistake?','He admitted it and offered to replace the seal.','He denied it and blamed a colleague.','He bought the building.','own.s4 means admit a fault.','meaning')]);
P('owner','From own + -er; it names the person or group that possesses something.',C('owner.s1','通用','The shop owner posted the repair hours on the door and left a number for customers to call.','店主把维修营业时间贴在门上，并留了一个供顾客拨打的号码。','The shop owner / posted the repair hours / on the door / and left a number for customers to call.','owner.s1 指拥有某物的人或团体。','店主拥有并经营这家店。','word-formation'),M('The shop owner rented the premises for one afternoon but had no ownership or control of the shop.','The shop owner held the shop’s title and made decisions about its operation.','短暂租用场地不等于拥有这家店。','distinction'),[Q(1,'What did the shop owner post?','The repair hours.','A list of the shop’s former owners only.','A notice about an opera overture.','owner.s1 names the person who owns the shop.'),Q(1,'Who is the owner of a bicycle?','The person who possesses it.','The mechanic who repairs it once.','A passerby who sees it.','Ownership, rather than a one-time service, makes someone its owner.'),Q(1,'Which noun names the person who owns something?','owner','owing','overuse','Owner is formed to name the possessor.'),Q(1,'What does -er mean in owner?','A person who owns.','An object that is being owned in the past.','A place where something is weighed.','The suffix forms an agent noun from own.','word-formation')]);
P('ownership','From owner + -ship; the suffix names the state, right, or relationship of owning something.',C('ownership.s1','法律','The deed confirmed the family’s ownership of the lakeside cabin after the final transfer was recorded.','最终转让登记后，契约确认了这家人对湖边小屋的所有权。','The deed confirmed the family’s ownership / of the lakeside cabin / after the final transfer / was recorded.','ownership.s1 指拥有某物的状态或产权。','契约记录了产权归属。','word-formation'),M('The signed deed confirmed that the family had no ownership of the cabin and no legal claim to it.','The signed deed confirmed the family’s ownership of the cabin.','没有产权或法律权利就不能称为 ownership。','meaning'),[Q(1,'What did the deed confirm?','The family’s right to the cabin.','The family’s debt for a damaged book.','The cabin’s repair schedule only.','ownership.s1 is the state or legal right of owning.'),Q(1,'Which document can establish ownership of a house?','A registered deed naming the property holder.','A visitor’s ticket to the house.','A grocery receipt from nearby.','The deed records legal ownership.'),Q(1,'What does ownership mean?','The state or right of possessing something.','The act of borrowing without permission.','A person who organizes an event.','Ownership names the relation of owning.'),Q(1,'Which word is ownership built from?','owner + -ship','over + -time','own + -less','The suffix -ship forms a noun for a status or relation.','word-formation')]);
P('ox','From Old English oxa; the plural is oxen. It usually names a grown male of the cattle family used for farm work, and also appears in a few fixed comparisons.',[C('ox.s1','农业','The farmer used an ox to pull the heavy cart across the muddy field.','农夫用一头公牛把沉重的车拉过泥泞的田地。','The farmer used an ox / to pull the heavy cart / across the muddy field.','ox.s1 指牛科成年雄性，常用于农活。','牛被用来拉农车。'),C('ox.s2','习语','The guide called the patient draft animal “as strong as an ox,” using the familiar comparison for great strength.','导游用常见比喻称这头耐力强的役畜“像牛一样壮”。','The guide called the patient draft animal / “as strong as an ox” / using the familiar comparison / for great strength.','ox.s2 在少数固定短语中可泛指牛，如 as strong as an ox。','固定短语用牛象征力量。')],M('The farmer used an ox to pull the cart, but described it as a young female calf.','The farmer used a grown male ox to pull the cart.','ox 通常指成年雄性牛，不能把同一只动物说成母牛犊。','meaning'),[Q(1,'What did the farmer use the ox to do?','Pull a cart through the field.','Carry a library fine.','Serve as a musical instrument.','ox.s1 is a working male bovine.'),Q(2,'What does “as strong as an ox” communicate?','Great physical strength.','A high level of anxiety.','A very small workload.','The fixed comparison uses an ox as a symbol of strength.'),Q(1,'What is the usual plural of ox?','oxen','oxesies','oxs','The conventional plural is oxen.','word-formation'),Q(2,'Which phrase uses ox in a fixed comparison?','as strong as an ox','as silent as an overture','as late as overtime','The first is a common fixed comparison with ox.','collocation')]);
P('Oxford','The place-name is recorded in Old English as Oxnaford, formed from oxen + ford, a river crossing used by oxen; it names the English city or its university.',[C('Oxford.s1','地理','They spent the weekend in Oxford, walking beside the Thames and visiting the city’s old college buildings.','他们在牛津度过周末，沿泰晤士河散步并参观城里的古老学院建筑。','They spent the weekend in Oxford / walking beside the Thames / and visiting / the city’s old college buildings.','Oxford.s1 指英格兰的大学城牛津。','泰晤士河与学院建筑表明句中指这座城市。'),C('Oxford.s1','教育','After receiving her offer, Mei accepted a place at Oxford and began preparing for her university course.','收到录取通知后，梅接受了牛津大学的名额，并开始为大学课程做准备。','After receiving her offer / Mei accepted a place at Oxford / and began preparing / for her university course.','Oxford.s1 也可指牛津大学本身。','接受大学名额的语境指大学。')],M('The student accepted a place at Oxford, then described it as a city in Scotland on the North Sea coast.','The student accepted a place at Oxford, the English university city.','Oxford 位于英格兰内陆，不是苏格兰的北海沿岸城市。','meaning'),[Q(1,'Where did they spend the weekend?','In the English city of Oxford.','In a seaside town in Scotland.','In the university’s chemistry lab only.','Oxford.s1 can name the city.'),Q(1,'What did Mei accept a place at?','The University of Oxford.','A ford for cattle.','A local farm market.','Oxford.s1 can refer to the university.'),Q(1,'Which feature helps identify Oxford in this example?','Its historic colleges beside the Thames.','A coastline on the North Sea.','A desert crossing.','The sentence describes Oxford in England.'),Q(1,'What does the old name Oxnaford combine?','Oxen and ford.','Oxygen and sphere.','Over and staff.','The place-name refers to a ford used by oxen.','word-formation')]);
P('oxidation','From oxide + -ation, through French; oxidation names the process in which a substance combines with oxygen.',C('oxidation.s1','科学','The iron railing developed orange rust through oxidation after years of rain and exposure to air.','铁栏杆经年受雨水和空气影响，通过氧化形成了橙色铁锈。','The iron railing developed orange rust / through oxidation / after years of rain / and exposure to air.','oxidation.s1 指物质与氧结合的过程。','铁与空气中的氧反应形成锈。','word-formation'),M('The iron railing showed oxidation even though it had been sealed from oxygen and underwent no reaction.','The iron railing showed oxidation after iron reacted with oxygen in moist air.','没有氧参与反应的情况下不能用此例证明氧化。','meaning'),[Q(1,'What caused rust on the railing?','Iron reacted with oxygen over time.','The railing was painted with a new color.','A court reversed a decision.','oxidation.s1 is the process of combining with oxygen.'),Q(1,'Which change is oxidation?','A cut apple browns after exposure to air.','Ice melts when warmed.','A paper label is removed.','The apple’s reaction with oxygen is oxidation.'),Q(1,'What does oxidation name?','A chemical process involving combination with oxygen.','A type of night bird.','An extra period in a sports match.','The word refers to a chemical reaction with oxygen.'),Q(1,'Which base is visible in oxidation?','oxide','owl','overtime','Oxidation is formed from oxide with -ation.','word-formation')]);
P('oxide','From oxygen + -ide, following the chemical naming pattern; it is a compound of oxygen with another element, or a thin reacted surface layer.',[C('oxide.s1','化学','Magnesium oxide formed when magnesium burned in oxygen and combined with the gas.','镁在氧气中燃烧并与氧结合后形成氧化镁。','Magnesium oxide formed / when magnesium burned in oxygen / and combined / with the gas.','oxide.s1 指氧与至少另一种元素组成的化合物。','镁和氧结合生成氧化物。'),C('oxide.s2','材料','A thin oxide layer on the aluminum surface slowed further corrosion in the outdoor frame.','铝表面的一层薄氧化膜减缓了户外框架的进一步腐蚀。','A thin oxide layer / on the aluminum surface / slowed further corrosion / in the outdoor frame.','oxide.s2 指表面与氧反应后形成的薄层。','表面氧化层有保护作用。')],M('Magnesium oxide contained magnesium but no oxygen, so the chemist labeled it an oxide.','Magnesium oxide contained magnesium bonded with oxygen.','oxide 是含氧化合物，不含氧就不符合定义。','meaning'),[Q(1,'How did magnesium oxide form in the example?','Magnesium combined with oxygen.','Magnesium combined with nitrogen only.','Aluminum paint covered the frame.','oxide.s1 is a compound of oxygen and another element.'),Q(2,'What did the thin oxide layer do?','It slowed further corrosion of the aluminum.','It made the frame dissolve instantly.','It increased the wood’s weight.','oxide.s2 is a surface layer formed by reaction with oxygen.'),Q(1,'Which substance is an oxide?','A compound of iron and oxygen.','Pure oxygen with no other element.','A mixture of sand and water only.','An oxide contains oxygen combined with another element.'),Q(2,'Which phrase refers to a surface film?','an oxide layer on aluminum','magnesium oxide as a bulk compound','oxygen in a cylinder','The first phrase describes the thin surface layer sense.','distinction')]);
P('oxidizable','From oxidize + -able; it means capable of undergoing oxidation in a chemical reaction.',C('oxidizable.s1','化学','The exposed iron sample was oxidizable, so the lab stored it in dry conditions to slow its reaction with oxygen.','暴露的铁样品能够被氧化，因此实验室将它存放在干燥环境中，以减缓它与氧的反应。','The exposed iron sample was oxidizable / so the lab stored it / in dry conditions / to slow its reaction with oxygen.','oxidizable.s1 指能够在化学反应中被氧化。','铁暴露后能与氧反应。','word-formation'),M('The metal was labeled oxidizable even though testing showed it could not react with oxygen under any tested condition.','The metal was labeled oxidizable because it reacted with oxygen during testing.','实验未能显示与氧反应时，不能据此断言该材料可氧化。','meaning'),[Q(1,'Why did the lab store the iron sample carefully?','It could undergo oxidation.','It could not react with any substance.','It was already a glass container.','oxidizable.s1 means able to be oxidized.'),Q(1,'Which material is oxidizable in the test?','A metal that reacts with oxygen.','A substance that cannot undergo the reaction.','A container with no chemical contents.','The first material is capable of oxidation.'),Q(1,'What does oxidizable mean?','Able to undergo oxidation.','Already fully dissolved in water.','Able to prevent every reaction.','The suffix -able signals capability.'),Q(1,'Which base verb forms oxidizable?','oxidize','owe','overturn','Oxidizable is built from oxidize plus -able.','word-formation')]);
P('oxidize','From oxygen + -ize; it means combine with oxygen or cause a substance to do so.',C('oxidize.s1','科学','Moist air can oxidize an unprotected iron nail, gradually producing a reddish layer of rust.','潮湿空气会使未受保护的铁钉氧化，逐渐形成红褐色铁锈层。','Moist air can oxidize / an unprotected iron nail / gradually producing / a reddish layer of rust.','oxidize.s1 指与氧化合，或使某物与氧化合。','空气中的氧参与铁钉生锈。','word-formation'),M('The sealed iron nail oxidized after remaining in a vacuum with no oxygen or other oxidizing agent.','The iron nail oxidized after exposure to moist air containing oxygen.','例句宣称真空中无氧却发生氧化，缺少题述的反应条件。','context'),[Q(1,'What can moist air do to an unprotected iron nail?','Oxidize it and form rust.','Turn it into a living organism.','Make it heavier without any reaction.','oxidize.s1 means combine with oxygen or cause that reaction.'),Q(1,'Which verb describes oxygen reacting with iron?','oxidize','overwinter','overtire','Oxidize is the chemical verb for combining with oxygen.'),Q(1,'Which example uses oxidize causatively?','The chemical oxidized the metal surface.','The metal oxidized in air.','The rust was orange.','The first sentence has an agent causing oxidation.'),Q(1,'What does the suffix -ize do in oxidize?','Forms a verb meaning cause or undergo a process.','Makes the word a plural noun.','Marks a past event only.','-ize commonly forms verbs from nouns or adjectives.','word-formation')]);
P('oxygen','From French oxygène, coined from Greek oxy- “sharp, acid” + -genes “producing”; it names the element needed for animal life and the gas supplied to support breathing.',[C('oxygen.s1','化学','Oxygen makes up part of the air, and each oxygen atom has the chemical symbol O.','氧是空气的一部分，每个氧原子的化学符号是 O。','Oxygen makes up part of the air / and each oxygen atom / has the chemical symbol O.','oxygen.s1 指空气中的无色元素/气体，是人和动物生存所需。','注意元素符号 O 与氧气分子 O₂ 不同。'),C('oxygen.s2','医学','The paramedic connected the patient to an oxygen cylinder after checking that the mask fitted securely.','急救人员确认面罩贴合后，将患者接上了氧气瓶。','The paramedic connected the patient / to an oxygen cylinder / after checking / that the mask fitted securely.','oxygen.s2 指从气罐供给、帮助患者呼吸的医用氧气。','氧气瓶为患者提供辅助呼吸用氧。')],M('The paramedic removed the oxygen supply from a patient who could not breathe and described the cylinder as oxygen support.','The paramedic supplied oxygen from the cylinder to help the patient breathe.','撤去供氧与提供氧气支持意思相反。','meaning'),[Q(1,'What is the chemical symbol for an oxygen atom?','O','O3','Ox','oxygen.s1 names the element whose atomic symbol is O.'),Q(2,'Why did the paramedic connect an oxygen cylinder?','To help the patient breathe.','To measure the patient’s height.','To produce rust on the mask.','oxygen.s2 is medical oxygen supplied from a tank.'),Q(1,'Which statement is chemically precise?','An oxygen atom has symbol O; oxygen gas commonly occurs as O₂.','An oxygen atom has symbol O₃.','Oxygen gas contains no oxygen atoms.','The first distinguishes the element symbol from its common molecular form.'),Q(2,'Which use refers to a medical supply?','The clinic gave oxygen through a mask.','Oxygen is an element in air.','An oxide formed on the railing.','The first describes supplied medical oxygen.','distinction')]);
P('oxygenated','From oxygen + -ate + -ed; it describes a fluid or tissue to which oxygen has been added, especially blood leaving the lungs.',C('oxygenated.s1','医学','The blood leaving the lungs was oxygenated before it traveled through the arteries to the rest of the body.','离开肺部的血液在通过动脉流向身体其他部位前已经完成氧合。','The blood leaving the lungs / was oxygenated / before it traveled through the arteries / to the rest of the body.','oxygenated.s1 指加入氧气的，尤指离开肺部的血液。','血液经肺部获得氧气后流向全身。','word-formation'),M('Blood leaving healthy lungs was described as oxygenated even though the lungs had removed oxygen from it.','Blood leaving the lungs was oxygenated after taking up oxygen there.','肺部若从血液中移除氧气，血液就不是因此而氧合。','meaning'),[Q(1,'Where was the blood oxygenated in the example?','In the lungs.','In the stomach.','In a dry storage room.','oxygenated.s1 especially describes blood after it leaves the lungs.'),Q(1,'What does oxygenated mean?','Having oxygen added.','Having all oxygen removed.','Being changed into an oxide layer.','The adjective describes oxygen being present or added.'),Q(1,'Which blood is oxygenated in the circulation?','Blood that has taken up oxygen in the lungs.','Blood from which the lungs have just removed oxygen.','Blood with no gas exchange.','Oxygenated blood has received oxygen.'),Q(1,'How is oxygenated formed?','oxygen + -ate + -ed','oyster + -catcher','over + -turn','The adjective derives from oxygenate with -ed.','word-formation')]);
P('oyster','From Old French oistre, from Latin ostrea and Greek ostreon “shell”; an oyster is a two-shelled sea animal eaten as food and sometimes associated with pearls.',C('oyster.s1','饮食','The restaurant served grilled oyster with lemon, and the menu noted that the shellfish came from a local farm.','餐厅供应烤牡蛎配柠檬，菜单注明这种贝类来自当地养殖场。','The restaurant served grilled oyster / with lemon / and the menu noted / that the shellfish came from a local farm.','oyster.s1 指有两扇壳、可食用、有时产珍珠的海生贝类。','菜单明确说明是可食用的贝类。'),M('The cook served a grilled oyster but described it as a land mammal with fur and paws.','The cook served a grilled oyster, a shelled sea animal.','牡蛎是有壳的海生动物，不是有毛的陆生哺乳动物。','meaning'),[Q(1,'Where did the restaurant’s oyster come from?','A local shellfish farm.','A forest nest.','A university library.','oyster.s1 is a shellfish that lives in the sea.'),Q(1,'Which feature identifies an oyster?','A hinged shell around a sea animal.','Feathers and a flat face.','A hard mineral crystal with no animal.','Oysters are marine animals with shells.'),Q(1,'What may some oysters produce?','Pearls.','Oxen.','Ozone gas.','Some oysters produce pearls.'),Q(1,'Which dish contains an oyster?','Grilled shellfish with lemon.','A bird’s nest with grain.','An iron oxide coating.','Oysters are edible shellfish.','meaning')]);
P('oystercatcher','A compound of oyster + catcher; it names a black-and-white shorebird that feeds on shellfish.',C('oystercatcher.s1','生物','An oystercatcher probed the mud at low tide with its long bill and pulled a small mussel from the shore.','退潮时，一只蛎鹬用长喙探入泥滩，从岸边取出一只小贻贝。','An oystercatcher probed the mud / at low tide / with its long bill / and pulled a small mussel from the shore.','oystercatcher.s1 指以贝类为食的黑白滨鸟。','蛎鹬在潮间带寻找贝类。','word-formation'),M('The guide identified a black-and-white shorebird that fed on shellfish as an oystercatcher, then said the name referred to a mammal that hunts mice.','The guide identified the shellfish-eating shorebird as an oystercatcher.','oystercatcher 是鸟名，不是捕鼠哺乳动物。','meaning'),[Q(1,'What did the oystercatcher find at low tide?','A small mussel.','A medical oxygen tank.','A pearl inside a museum case.','oystercatcher.s1 is a shorebird that feeds on shellfish.'),Q(1,'Where would an oystercatcher most likely feed?','On a tidal shore among shellfish.','In a dry desert cave.','In a city office at night.','The bird’s food and habitat are coastal.'),Q(1,'What kind of animal is an oystercatcher?','A black-and-white shorebird.','A marine shellfish.','A farm animal used to pull a cart.','It is a bird that hunts shellfish.'),Q(1,'Which parts form oystercatcher?','oyster + catcher','oxygen + sphere','over + winter','The compound names a bird that catches or feeds on shellfish.','word-formation')]);
P('ozone','From French ozone, coined from Greek ozein “to smell”; it names the O₃ form of oxygen, the atmospheric ozone layer, and in older usage fresh sea air.',[C('ozone.s1','化学','Ozone is a reactive gas whose molecule contains three oxygen atoms, so its formula is O₃.','臭氧是一种活性气体，其分子含三个氧原子，因此分子式为 O₃。','Ozone is a reactive gas / whose molecule contains / three oxygen atoms / so its formula is O₃.','ozone.s1 指由三个氧原子构成的臭氧。','O₃ 表示每个分子含三个氧原子。'),C('ozone.s2','环境','The report tracked ozone in the upper atmosphere, where the ozone layer absorbs much harmful ultraviolet radiation.','报告监测了高层大气中的臭氧；臭氧层会吸收大量有害紫外线。','The report tracked ozone / in the upper atmosphere / where the ozone layer absorbs / much harmful ultraviolet radiation.','ozone.s2 指高空中吸收太阳有害射线的臭氧层。','高空臭氧层具有吸收紫外线的作用。'),C('ozone.s3','旧用法','In an old travel diary, the writer praised the “ozone” of the seaside, using an earlier word for fresh air rather than a measured gas level.','在一本旧旅行日记里，作者称赞海边的“清新空气”，用的是 ozone 的旧义，而非测得的气体浓度。','In an old travel diary / the writer praised the “ozone” / of the seaside / using an earlier word for fresh air.','ozone.s3 旧时可指清新空气，尤其是海边空气；现代写作中应标明这是旧用法。','例句明确将其作为历史用词，而非空气化学分析。')],M('The chemist labeled ordinary O₂ oxygen molecules as ozone even though each molecule contained only two oxygen atoms.','The chemist labeled O₃ molecules as ozone and O₂ as ordinary oxygen gas.','臭氧是 O₃；O₂ 是常见氧气分子。','distinction'),[Q(1,'What is the formula of ozone molecules?','O₃','O₂','CO₂','ozone.s1 contains three oxygen atoms per molecule.'),Q(2,'Where is the ozone layer discussed in the report?','In the upper atmosphere.','In the restaurant’s oyster dish.','At the bottom of the ocean only.','ozone.s2 refers to the high-atmosphere layer.'),Q(3,'What did “ozone” mean in the old travel diary?','Fresh sea air in an older usage.','A measured O₃ level in a laboratory report.','A type of shorebird.','ozone.s3 is an older figurative use for fresh air.'),Q(1,'Which statement distinguishes oxygen and ozone correctly?','O₂ is ordinary oxygen gas; O₃ is ozone.','O₂ and O₃ are the same formula.','O₃ contains no oxygen atoms.','Ozone has three oxygen atoms, unlike O₂.','distinction')]);
P('ozonosphere','From ozone + sphere; it names the upper-atmosphere region in which ozone absorbs much of the Sun’s ultraviolet radiation.',C('ozonosphere.s1','环境','The ozonosphere absorbs much incoming ultraviolet radiation high above the Earth, helping shield life at the surface.','臭氧层在地球高空吸收大量入射紫外线，帮助保护地表生命。','The ozonosphere absorbs much incoming ultraviolet radiation / high above the Earth / helping shield life / at the surface.','ozonosphere.s1 指高层大气中吸收大量紫外线的区域。','该区域的臭氧具有防护作用。','word-formation'),M('The report said the ozonosphere was the deep ocean layer that absorbs ultraviolet light beneath the seabed.','The report said the ozonosphere is an upper-atmosphere region that absorbs ultraviolet light.','ozonosphere 位于高层大气，不在海底。','meaning'),[Q(1,'What does the ozonosphere absorb?','Much ultraviolet radiation from the Sun.','All sound waves from the ocean.','The oxygen inside a medical cylinder.','ozonosphere.s1 is the upper-atmosphere region that absorbs UV.'),Q(1,'Where is the ozonosphere?','High in Earth’s atmosphere.','Under the seabed.','Inside a garden shed.','The term names an atmospheric region.'),Q(1,'Why is the ozonosphere important to life at the surface?','It helps shield life by absorbing harmful ultraviolet radiation.','It creates every cloud and rainfall event.','It supplies all medical oxygen directly.','Its ozone absorbs much UV radiation.'),Q(1,'What does sphere contribute in ozonosphere?','A region or layer surrounding Earth.','A type of shellfish.','A process of oxidation.','Sphere names a surrounding region here.','word-formation')]);
P('pace','From Latin passus “step,” via French; pace can mean the speed of movement or development, a single step, or walking back and forth steadily.',[C('pace.s1','通用','The nurse adjusted her walking pace to match the older patient’s slower steps.','护士调整了步速，配合年长患者较慢的步伐。','The nurse adjusted her walking pace / to match / the older patient’s slower steps.','pace.s1 指行走速度，也指事情发展的速度。','句中 pace 表示走路快慢。'),C('pace.s2','通用','After several paces from the gate, the hikers stopped to check the trail map.','从大门走出几步后，徒步者停下来查看路线图。','After several paces from the gate / the hikers stopped / to check the trail map.','pace.s2 指一步或一步的距离。','several paces 指几步的距离。'),C('pace.s3','通用','Unable to sit still before the interview, Omar paced the hallway while reviewing his notes.','面试前坐不住，奥马尔一边复习笔记，一边在走廊里来回踱步。','Unable to sit still before the interview / Omar paced the hallway / while reviewing his notes.','pace.s3 作动词，指以缓慢而均匀的步子来回走。','他在走廊里来回走动。')],M('The nurse slowed her pace by walking faster to stay ahead of the patient.','The nurse slowed her pace by taking shorter, slower steps beside the patient.','加快步速不是放慢步速。','meaning'),[Q(1,'What did the nurse adjust?','How quickly she walked.','The distance from the gate to the trail.','The hallway’s width.','pace.s1 is the speed of walking.'),Q(2,'How far did the hikers walk before stopping?','Several steps from the gate.','Several hours from the city.','No distance at all.','pace.s2 can mean a step or step-length.'),Q(3,'What did Omar do in the hallway?','He walked back and forth steadily.','He ran outside to catch a bus.','He sat without moving.','pace.s3 is the verb for steady walking, often while thinking or waiting.'),Q(1,'Which sentence uses pace for rate of progress?','The project’s pace slowed after the supplier closed.','She took one pace toward the door.','He paced the corridor.','The first refers to the speed of development.','distinction')]);
P('pacific','From Latin pacificus “peace-making,” from pax “peace”; as a noun it names the ocean between Asia and the Americas, and as an adjective it means peaceful.',[C('pacific.s1','地理','The research vessel crossed the Pacific from Japan toward the coast of California.','科研船从日本横渡太平洋，驶向加利福尼亚海岸。','The research vessel crossed the Pacific / from Japan / toward the coast of California.','pacific.s1 作专名，指亚洲与美洲之间的太平洋。','航线跨越日本与北美之间的大洋。'),C('pacific.s2','通用','The two neighbors took a pacific approach to the boundary dispute and settled it through a calm discussion.','两位邻居以和平方式处理边界争议，通过平静交谈解决了问题。','The two neighbors took a pacific approach / to the boundary dispute / and settled it / through a calm discussion.','pacific.s2 作形容词，指平和、不想争斗的。','他们选择平静协商而非冲突。')],M('The neighbors chose a pacific response by starting a fight and refusing every peaceful discussion.','The neighbors chose a peaceful, pacific response by discussing the boundary calmly.','主动挑起争斗与 pacific 的和平含义相反。','distinction'),[Q(1,'Which ocean did the vessel cross?','The Pacific.','The Mediterranean.','The Arctic lake.','pacific.s1 is the ocean between Asia and the Americas.'),Q(2,'How did the neighbors take a pacific approach?','They discussed the dispute calmly.','They attacked one another.','They refused to speak and escalated the dispute.','pacific.s2 means peaceful or not wanting to fight.'),Q(1,'What part of speech is Pacific in “crossed the Pacific”?','A proper noun naming an ocean.','An adjective describing calm behavior.','A verb meaning to calm someone.','The example uses Pacific as the name of an ocean.'),Q(2,'Which action is pacific?','Seeking a nonviolent agreement.','Threatening violence to win.','Blocking every attempt at discussion.','A pacific action aims for peace.','meaning')]);
P('pacifier','From pacify + -er; it can name a teat a baby sucks for comfort or a person/thing that calms conflict.',[C('pacifier.s1','育儿','The baby dropped the pacifier, so the parent washed it before giving it back.','婴儿把安抚奶嘴掉在地上，家长洗净后才还给他。','The baby dropped the pacifier / so the parent washed it / before giving it back.','pacifier.s1 指给婴儿吮吸的橡胶或硅胶奶嘴。','奶嘴被清洗后交还给婴儿。'),C('pacifier.s2','社会','A trusted mediator acted as a pacifier during the tense meeting and helped both groups lower their voices.','一位受信任的调停者在紧张的会议中平息了冲突，帮助双方降低了音量。','A trusted mediator acted as a pacifier / during the tense meeting / and helped both groups / lower their voices.','pacifier.s2 指平息怒气或冲突的人或事物。','调停者缓和了双方的紧张情绪。')],M('The parent called a metal spoon a pacifier and gave it to the baby to suck without checking its safety.','The parent gave the baby a clean, age-appropriate silicone pacifier.','婴儿奶嘴应是专用的安全物品，不应把金属勺子当作 pacifier。','context'),[Q(1,'Why did the parent wash the pacifier?','The baby had dropped it.','It had mediated a meeting.','It was a rubber boot.','pacifier.s1 is the baby’s sucking teat.'),Q(2,'How did the mediator act as a pacifier?','By helping both groups calm down.','By giving a baby a teat.','By raising both groups’ voices.','pacifier.s2 is something or someone that calms conflict.'),Q(1,'Which object is a baby pacifier?','A clean silicone teat for sucking.','A metal tool used for repairs.','A paper packet of medicine.','The first is the item described by pacifier.s1.'),Q(2,'Which person could be called a pacifier in a conflict?','A mediator who calms the parties.','A witness who makes both sides angrier.','A courier delivering a package.','A pacifier can be someone who restores calm.','meaning')]);
P('pacifist','From pacifism + -ist, ultimately from Latin pax, pacis “peace”; a pacifist believes war and violence are wrong.',C('pacifist.s1','政治','The pacifist refused military service and argued that disputes should be settled without violence.','这位和平主义者拒绝服兵役，并主张应以非暴力方式解决争端。','The pacifist refused military service / and argued / that disputes should be settled / without violence.','pacifist.s1 指反对战争与暴力的人。','拒绝军事行动并主张非暴力体现其立场。','word-formation'),M('The speaker called herself a pacifist while insisting that every disagreement should be settled by war.','The speaker called herself a pacifist because she opposed war and supported nonviolent solutions.','主张以战争解决争端与和平主义立场自相矛盾。','distinction'),[Q(1,'What did the pacifist argue for?','Settling disputes without violence.','Using war to resolve every disagreement.','Expanding military action.','pacifist.s1 describes opposition to war and violence.'),Q(1,'Which person is a pacifist?','Someone who believes war is always wrong.','Someone who promotes armed conflict.','Someone who repairs a peace treaty.','The first matches the stated belief.'),Q(1,'What is the central belief of a pacifist?','War and violence are wrong.','All conflicts should be ignored.','Every treaty must be broken.','A pacifist rejects war and violence.'),Q(1,'Which suffix names a person who supports a belief?','-ist','-ness','-ward','Pacifist uses -ist to name an adherent.','word-formation')]);
P('pacify','From Latin pacificare “make peace,” from pax “peace”; it means calm an upset person or bring a region to peace, sometimes by force.',[C('pacify.s1','通用','The teacher paused the game to pacify the upset child and listened while she explained what had happened.','老师暂停游戏来安抚难过的孩子，并听她解释事情经过。','The teacher paused the game / to pacify the upset child / and listened / while she explained what had happened.','pacify.s1 指使生气或不安的人平静下来。','倾听并安慰孩子让她平静。'),C('pacify.s2','政治','The occupying army tried to pacify the region by force, but resentment continued among local residents.','占领军试图以武力平定该地区，但当地居民仍然心怀不满。','The occupying army tried / to pacify the region by force / but resentment continued / among local residents.','pacify.s2 指使国家或地区恢复平静，有时依靠武力。','句中描述的是用武力控制地区。')],M('The teacher pacified the upset child by shouting over her and refusing to listen.','The teacher pacified the upset child by listening calmly and offering reassurance.','粗暴斥责可能使人更不安，不是安抚。','meaning'),[Q(1,'How did the teacher pacify the child?','By listening and letting her explain.','By shouting over her.','By forcing her to continue the game.','pacify.s1 means calm an upset person.'),Q(2,'What did the occupying army try to do?','Bring the region under control, sometimes by force.','Comfort one child after a game.','Write a pacifist poem.','pacify.s2 can mean restore order in a region.'),Q(1,'Which action can pacify an angry guest?','Listen, acknowledge the concern, and offer a solution.','Mock the guest and raise your voice.','Ignore the guest and walk away.','The first action is intended to calm the person.'),Q(2,'Which use of pacify refers to a region?','The authorities tried to pacify the province after unrest.','The parent pacified a crying toddler.','The baby sucked a pacifier.','The first sentence uses pacify for restoring regional calm.','distinction')]);
P('pack','From Middle English pak, probably from a Germanic source; pack can mean a bundle, a group of animals/people, putting belongings in luggage, or filling a place tightly.',[C('pack.s1','通用','She carried a pack of playing cards and a bundle of maps for the long train ride.','她带了一副扑克牌和一捆地图，准备乘坐长途火车。','She carried a pack of playing cards / and a bundle of maps / for the long train ride.','pack.s1 指装有一组东西的包、盒或捆。','扑克牌以一组形式装在一起。'),C('pack.s2','自然','A pack of wolves moved across the snowy ridge together while searching for food.','一群狼一同行过雪岭，寻找食物。','A pack of wolves / moved across the snowy ridge together / while searching for food.','pack.s2 指一起生活或捕猎的一群动物。','狼群共同活动并寻找食物。'),C('pack.s3','旅行','Before the early flight, Jo packed a sweater, medication, and her passport into a small suitcase.','赶早班飞机前，乔把毛衣、药品和护照装进小行李箱。','Before the early flight / Jo packed a sweater, medication, and her passport / into a small suitcase.','pack.s3 作动词，指旅行前把东西装进行李。','旅行物品被放进行李箱。'),C('pack.s4','场所','Fans packed the small gym so tightly that late arrivals watched the game from the hallway.','球迷把小体育馆挤得满满当当，来晚的人只好在走廊看比赛。','Fans packed the small gym / so tightly / that late arrivals watched the game / from the hallway.','pack.s4 作动词，指把人或物塞得很满。','观众挤满了体育馆。')],M('The family packed for the trip by leaving every suitcase empty and putting no belongings inside.','The family packed for the trip by putting clothes and essentials into their suitcases.','pack luggage 是把行李装好，空着箱子没有完成打包。','meaning'),[Q(1,'What did Jo carry in a pack?','A set of playing cards.','A group of wolves.','A gym full of fans.','pack.s1 can mean a container or bundle of items.'),Q(2,'What does a pack of wolves mean?','A group of wolves living or moving together.','One wolf’s travel bag.','A tightly filled gym.','pack.s2 means a group of animals.'),Q(3,'What did Jo pack into the suitcase?','A sweater, medication, and passport.','A pack of wolves.','A crowd of fans.','pack.s3 is putting belongings into luggage.'),Q(4,'Why did late arrivals stay in the hallway?','Fans had packed the gym tightly.','The gym was empty.','The fans had packed their bags and left.','pack.s4 means fill a place with people or things.','distinction')]);
P('package','From Middle Dutch pakken “to pack,” via French; it names a wrapped parcel, a set offered together, or software supplied as one product, and can also mean wrap or prepare goods for sale.',[C('package.s1','邮递','The courier scanned the package before placing it in the locked delivery cabinet.','快递员扫描包裹后，把它放进了上锁的收件柜。','The courier scanned the package / before placing it / in the locked delivery cabinet.','package.s1 指为携带或邮寄而包好的一件物品。','快递柜中的物品是待送包裹。'),C('package.s2','商业','The supplier offered a service package that included installation, training, and one year of support.','供应商提供了一套服务方案，包括安装、培训和一年的支持。','The supplier offered a service package / that included installation, training, / and one year / of support.','package.s2 指作为整体提供的一揽子服务、条件或方案。','多项服务作为一个整体出售。'),C('package.s3','商业','The company packages the tea in recyclable tins and labels each tin with its harvest date.','公司把茶叶装进可回收铁罐，并在每个罐子上标注采摘日期。','The company packages the tea / in recyclable tins / and labels each tin / with its harvest date.','package.s3 作动词，指包装商品或把商品做成可出售的形式。','茶叶被装罐并贴上标签。'),C('package.s4','计算机','The developer installed a software package that added charting tools to the data-analysis program.','开发者安装了一个软件包，为数据分析程序增加了绘图工具。','The developer installed a software package / that added charting tools / to the data-analysis program.','package.s4 指作为一件产品提供的程序或相关程序组。','安装的软件包增加了一组功能。')],M('The courier placed an unwrapped, loose collection of tools in a cabinet but called it a sealed package ready for shipping.','The courier wrapped the tools together in a labeled parcel before shipping them.','未包装的散放物品不是已封装的邮寄包裹。','meaning'),[Q(1,'What did the courier scan?','A wrapped parcel for delivery.','A bundle of wolves.','A software license only.','package.s1 is an item prepared for carrying or posting.'),Q(2,'What did the service package include?','Installation, training, and support together.','Only a delivery cabinet.','A set of unrelated software errors.','package.s2 bundles services as one offer.'),Q(3,'How does the company package tea?','It puts tea in recyclable tins and labels them.','It installs charts on a computer.','It leaves the tea loose in a truck.','package.s3 is the verb for preparing goods for sale.'),Q(4,'What did the software package add?','Charting tools to a data-analysis program.','A year of courier delivery.','Tea tins and labels.','package.s4 is a program or related programs sold as one product.','meaning')]);
P('packaging','From package + -ing; it names the boxes, wrapping, and design that protect a product and help present it for sale.',C('packaging.s1','商业','The new packaging used a cardboard insert to protect the glass jar and printed recycling instructions on the box.','新包装用纸板内衬保护玻璃罐，并在盒子上印了回收说明。','The new packaging used a cardboard insert / to protect the glass jar / and printed recycling instructions / on the box.','packaging.s1 指保护并展示商品所用的盒子、包裹物和设计。','包装既保护产品也提供回收信息。','word-formation'),M('The company called the jar’s packaging a bare bottle with no protective wrapping, container, or label.','The company’s packaging included a protective box and a clear label.','包装包括保护和呈现产品的材料与设计，不能说完全没有。','meaning'),[Q(1,'What protected the glass jar?','A cardboard insert in the packaging.','The courier’s software package.','A wolf pack.','packaging.s1 includes materials used to protect goods.'),Q(1,'Which belongs to product packaging?','A box design with a recycling label.','A customer’s walking pace.','A mediator at a meeting.','The box and its design are packaging.'),Q(1,'Why did the company print recycling instructions?','To guide disposal of the package.','To identify a wildlife group.','To explain a legal ruling.','The instructions are part of packaging information.'),Q(1,'Which word is packaging formed from?','package','pact','paddle','Packaging derives from package with -ing.','word-formation')]);
P('packed','From pack + -ed; it describes a place full of people or things, or belongings already put into a bag.',[C('packed.s1','通用','The train was packed at rush hour, and several passengers waited for the next one.','高峰时段列车挤满了人，几位乘客等下一班车。','The train was packed / at rush hour / and several passengers / waited for the next one.','packed.s1 指空间里挤满了人或物。','乘客太多导致列车拥挤。'),C('packed.s1','旅行','With her clothes and documents packed, Nina closed the suitcase and called a taxi.','衣物和文件都装好后，妮娜合上行李箱并叫了出租车。','With her clothes and documents packed / Nina closed the suitcase / and called a taxi.','packed.s1 也可指物品已装进行李。','东西已收进行李箱。')],M('The station was packed with commuters even though only one person was standing in the hall.','The station was packed with commuters because the hall was crowded with people.','仅有一人不构成挤满人群。','number'),[Q(1,'Why did some passengers wait for the next train?','The train was crowded.','The train had been packed into a suitcase.','The train had no destination.','packed.s1 means full of people or things.'),Q(1,'What had Nina done before calling a taxi?','She had put her clothes and documents into a suitcase.','She had unpacked every bag.','She had mailed the suitcase to a friend.','packed can mean belongings are already put into a bag.'),Q(1,'Which room is packed?','A hall so crowded that people cannot find seats.','An empty hall with one chair.','A storage room with all boxes removed.','Packed describes a tightly full space.'),Q(1,'Which sentence uses packed for luggage?','My bags are packed for tomorrow’s trip.','The bus was packed with fans.','They packed the bus themselves.','The first sentence describes belongings put into bags.','distinction')]);
P('packer','From pack + -er; it names a person employed to pack goods or a machine that performs the packing.',C('packer.s1','工作','The warehouse packer checked each order, wrapped fragile mugs, and placed them in labeled cartons.','仓库包装工核对每份订单，把易碎的杯子包好并放入贴有标签的纸箱。','The warehouse packer / checked each order / wrapped fragile mugs / and placed them in labeled cartons.','packer.s1 指包装货物的人或机器。','包装工负责包裹和装箱。','word-formation'),M('The warehouse packer unpacked every order and removed all cartons before shipping, yet the supervisor said the job was packing.','The warehouse packer wrapped the goods and placed them in cartons for shipment.','把货物拆开而非装箱，不符合 packer 的职责。','meaning'),[Q(1,'What did the warehouse packer do?','Wrapped mugs and placed them in cartons.','Designed the train schedule.','Negotiated a peace treaty.','packer.s1 names someone who packs goods.'),Q(1,'Which machine could be a packer?','A device that seals boxes on a production line.','A map used to orient hikers.','A microscope for viewing cells.','A packer can be a machine that packs items.'),Q(1,'Who is a packer?','A worker who prepares goods for shipping.','A customer who receives a parcel.','A driver who never handles cargo.','The packer performs the packing work.'),Q(1,'What does -er indicate in packer?','A person or machine that performs the action.','A past-tense verb.','A place where a package is stored.','-er forms an agent or instrument noun.','word-formation')]);
P('packet','From Middle English packet, a diminutive of pack; a packet can be a small container, a network data unit, or (in British informal use) a large sum of money.',[C('packet.s1','通用','She tore open a packet of seeds and poured them into the labeled envelope for spring planting.','她撕开一小包种子，把种子倒进贴好标签的信封，准备春季种植。','She tore open a packet of seeds / and poured them / into the labeled envelope / for spring planting.','packet.s1 指装商品的小袋或小盒。','种子装在小包里。'),C('packet.s2','计算机','The router dropped one data packet, so the video paused briefly while the stream requested it again.','路由器丢失了一个数据包，因此视频短暂停顿，等待流重新请求该数据。','The router dropped one data packet / so the video paused briefly / while the stream / requested it again.','packet.s2 指在网络上传送的一小块数据。','数据包丢失造成传输暂停。'),C('packet.s3','口语','The contractor made a packet selling the restored house, far more than she had expected to earn.','承包商卖掉修复后的房子赚了一大笔钱，远超她的预期。','The contractor made a packet / selling the restored house / far more than / she had expected to earn.','packet.s3 英式口语中指一大笔钱。','make a packet 是赚很多钱。')],M('The router sent the video as a packet of seeds through the network and planted it in the viewer’s garden.','The router sent a data packet through the network to the viewer’s device.','网络数据包不是实体种子包；两个义项不可混用。','distinction'),[Q(1,'What was inside the packet she opened?','Seeds.','A block of network data.','A large sum of money.','packet.s1 is a small closed container.'),Q(2,'Why did the video pause?','A data packet was dropped.','The contractor sold a house.','The seeds were planted.','packet.s2 is a unit of data sent across a network.'),Q(3,'What does “made a packet” mean here?','Earned a large amount of money.','Sent a network message.','Opened a small seed bag.','packet.s3 is an informal British expression for a large sum.'),Q(1,'Which packet can be torn open by hand?','A small bag of seeds.','A data unit traveling through a router.','The large sum she earned.','The first is a physical packet.','distinction')]);
P('pact','From Latin pactum “agreement,” from pacisci “to agree”; a pact can be a formal agreement between organizations or a serious promise between people.',[C('pact.s1','政治','The two countries signed a climate pact that set shared targets for cutting industrial emissions.','两国签署了一项气候协定，设定共同的工业减排目标。','The two countries signed a climate pact / that set shared targets / for cutting / industrial emissions.','pact.s1 指国家或组织之间的正式协定。','两国通过签署文件承诺共同目标。'),C('pact.s2','通用','The roommates made a pact to wake one another for morning classes and keep the kitchen clean.','室友们约定在早课前互相叫醒，并保持厨房整洁。','The roommates made a pact / to wake one another / for morning classes / and keep the kitchen clean.','pact.s2 指人们之间认真作出的共同承诺。','室友约定一起遵守两项规则。')],M('The countries signed a pact but explicitly agreed that neither side would follow any of its terms.','The countries signed a pact and agreed to follow its shared terms.','签订协定却明确拒绝遵守其条款，与协议的承诺性质矛盾。','meaning'),[Q(1,'What did the climate pact set?','Shared targets for reducing emissions.','A plan for a morning alarm only.','A list of network data packets.','pact.s1 is a formal agreement between countries.'),Q(2,'What did the roommates promise?','To wake one another and keep the kitchen clean.','To negotiate a treaty between nations.','To stop attending classes.','pact.s2 is a serious mutual promise.'),Q(1,'Which document is a pact?','A signed agreement between two governments.','A single person’s unspoken wish.','A shopping bag of seeds.','A pact is a formal agreement or serious commitment.'),Q(2,'Which is a personal pact?','Two friends promise to study together each Sunday.','Two countries exchange formal treaty documents.','A router sends data across a network.','The friends’ shared promise is the personal sense.','distinction')]);
P('pad','From Middle English pad, of uncertain origin; it can name a soft protective piece, a bound set of paper, an animal’s foot/finger cushion, or the verb meaning walk quietly.',[C('pad.s1','通用','He added a foam pad beneath the camera case to protect the lens during travel.','他在相机包下面加了一块泡沫垫，保护镜头免受旅途碰撞。','He added a foam pad / beneath the camera case / to protect the lens / during travel.','pad.s1 指用于保护、定型或清洁的厚软材料。','泡沫垫用于缓冲保护。'),C('pad.s2','办公','She wrote the delivery number on a pad of paper beside the telephone.','她在电话旁的便签本上记下了送货号码。','She wrote the delivery number / on a pad of paper / beside the telephone.','pad.s2 指一边装订在一起的一叠纸。','纸张装订在一边，供书写使用。'),C('pad.s3','生物','The cat’s soft paw pad left a faint print in the dust on the windowsill.','猫柔软的肉垫在窗台灰尘上留下了淡淡的印迹。','The cat’s soft paw pad / left a faint print / in the dust / on the windowsill.','pad.s3 指动物脚底的软肉，也可指手指肚。','脚垫接触灰尘留下印迹。'),C('pad.s4','通用','Trying not to wake the baby, Ren padded across the hallway in socks.','为了不吵醒婴儿，任穿着袜子轻轻走过走廊。','Trying not to wake the baby / Ren padded across the hallway / in socks.','pad.s4 作动词，指轻轻、安静地走。','袜子让脚步轻而安静。')],M('Trying to stay silent, Ren padded across the hall by stomping loudly in hard boots.','Trying to stay silent, Ren padded across the hall in soft slippers.','大声跺脚与轻步行走相反。','distinction'),[Q(1,'What protected the camera lens?','A foam pad.','A stack of unbound loose pages.','A cat’s foot.','pad.s1 is a soft protective piece.'),Q(2,'Where did she write the number?','On a bound pad of paper.','On the cat’s paw.','On the foam under the case.','pad.s2 is a paper pad.'),Q(3,'What left a faint print in the dust?','The cat’s paw pad.','The telephone number.','A sheet of foam.','pad.s3 is the soft underside of an animal’s foot.'),Q(4,'How did Ren move across the hallway?','Quietly in socks.','By stomping in hard boots.','By running and shouting.','pad.s4 means walk softly and quietly.','meaning')]);
P('padding','From pad + -ing; it names material inserted to soften something or fill an empty space.',C('padding.s1','家居','The chair’s new padding made the wooden seat more comfortable without changing its shape.','椅子新加的衬垫让木座更舒适，同时没有改变椅子的形状。','The chair’s new padding / made the wooden seat / more comfortable / without changing its shape.','padding.s1 指使物品变软或填充空隙的材料。','软材料垫在木座上以增加舒适度。','word-formation'),M('The upholsterer removed every cushion layer but claimed the bare wooden seat had extra padding.','The upholsterer added a foam layer as padding beneath the fabric.','没有加入任何软材料的裸木座不含衬垫。','meaning'),[Q(1,'What did the new padding do?','Made the seat more comfortable.','Made the chair’s wood harder.','Changed the owner’s legal rights.','padding.s1 is material that softens a surface.'),Q(1,'Which item is padding in a parcel?','Foam filling that protects a glass jar.','A paper list of addresses.','The jar’s glass lid.','Foam is inserted to protect and fill space.'),Q(1,'What does padding refer to?','Material used to soften or fill a space.','The act of walking quietly.','A group of wolves.','The noun names cushioning or filling material.'),Q(1,'Which word is padding derived from?','pad','pact','pace','Padding is formed from pad with -ing.','word-formation')]);
P('paddle','From a Germanic source via Middle English; paddle names a short, light oar and the verb means propel a small boat with one.',[C('paddle.s1','运动','The kayaker rested her paddle across the deck while she checked the map.','皮划艇运动员把桨横放在艇面上，同时查看地图。','The kayaker rested her paddle / across the deck / while she checked / the map.','paddle.s1 指小船用的短而轻的桨。','手持桨被放在艇面上。'),C('paddle.s2','运动','They paddled the canoe upstream in short strokes until they reached the sheltered inlet.','他们用短促的划桨动作逆流划独木舟，直到抵达避风的小湾。','They paddled the canoe upstream / in short strokes / until they reached / the sheltered inlet.','paddle.s2 作动词，指用桨划动小船。','用手桨产生推进力。')],M('The canoe moved upstream while the paddlers left every paddle on shore and made no strokes.','The canoe moved upstream as the paddlers used their paddles to propel it.','没有划桨动作就不能说船由 paddle 推进。','meaning'),[Q(1,'What did the kayaker rest across the deck?','A short, light oar.','A package of seeds.','A soft paper pad.','paddle.s1 is the handheld oar.'),Q(2,'How did they reach the inlet?','They used short paddle strokes.','They waited for the canoe to move by itself.','They turned the boat over.','paddle.s2 means propel a small boat using a paddle.'),Q(1,'Which object is a paddle?','A handheld blade used to move a kayak.','An oar fixed to a boat with a rowlock.','A decorative ship ornament.','A paddle is a short, light handheld oar.'),Q(2,'Which sentence uses paddle as a verb?','We paddled the canoe across the calm lake.','She packed a spare paddle.','The paddle lay beside the map.','The first sentence describes the action of propelling a boat.','grammar')]);
P('paddler','From paddle + -er; it names someone who propels a small boat with a handheld paddle rather than fixed oars.',C('paddler.s1','运动','Each paddler wore a life jacket and used a single-bladed paddle to steer the canoe through the narrow channel.','每位划桨者都穿着救生衣，并用单叶桨操纵独木舟通过狭窄水道。','Each paddler wore a life jacket / and used a single-bladed paddle / to steer the canoe / through the narrow channel.','paddler.s1 指使用手持桨划船的人。','划桨者手持单叶桨推进并控制独木舟。','word-formation'),M('The guide called the person a paddler even though the person sat ashore and never used a paddle.','The guide called the person a paddler because she propelled the canoe with a handheld paddle.','没有使用桨划船的人不符合此义。','meaning'),[Q(1,'What did each paddler use?','A single-bladed handheld paddle.','An oar fixed in a rowlock.','A packet of data.','paddler.s1 uses a handheld paddle.'),Q(1,'Who is a paddler?','Someone propelling a small boat with a paddle.','Someone sitting on shore without a paddle.','Someone who packs cargo into boxes.','The first person performs the defining action.'),Q(1,'What made the canoe controllable in the channel?','The paddler’s strokes and steering.','The paddler’s life jacket alone.','A fixed theater overture.','The paddler uses the paddle to steer and move the boat.'),Q(1,'How is paddler formed?','paddle + -er','pad + plural -s','pact + -less','-er names the person who paddles.','word-formation')]);
P('paddy','From Malay padi, ultimately from an Austronesian word for rice; it can mean a flooded rice field or rice still growing/in its husk.',[C('paddy.s1','农业','Workers repaired the banks around the paddy so water would cover the rice seedlings evenly.','工人修整稻田田埂，让水均匀覆盖秧苗。','Workers repaired the banks / around the paddy / so water would cover / the rice seedlings evenly.','paddy.s1 指灌水种植水稻的田。','田里蓄水以种植秧苗。'),C('paddy.s2','农业','The mill bought paddy from local farmers and removed the husks before selling polished rice.','碾米厂向当地农户收购稻谷，脱壳后再出售精米。','The mill bought paddy / from local farmers / and removed the husks / before selling polished rice.','paddy.s2 指仍在生长或尚未去壳的稻谷。','稻谷去壳后才成为精米。')],M('The mill called polished, husked rice paddy even though it had already removed the outer husks.','The mill called the unhulled grain paddy before removing its husk.','paddy 的稻谷义指仍带壳的谷粒或生长中的稻。','distinction'),[Q(1,'Why were the paddy banks repaired?','To hold water around rice seedlings.','To remove husks from polished rice.','To protect a boat from waves.','paddy.s1 is a flooded field for growing rice.'),Q(2,'What did the mill remove from the paddy?','The husks.','The paddy field’s water.','The farmers’ land titles.','paddy.s2 is rice before the husk is removed.'),Q(1,'Which place is a paddy?','A flooded field where rice is grown.','A dry warehouse holding finished flour.','A small bag of seeds.','Paddy.s1 is a rice-growing field.'),Q(2,'Which grain is paddy in this context?','Rice still in its husk.','Polished rice with the husk removed.','A packet of oats.','Paddy.s2 refers to rice before husking.','meaning')]);
P('pagan','From Late Latin paganus “country-dweller, civilian,” later used for a person outside Christianity; today it can describe an adherent of a religion classified as pagan.',C('pagan.s1','宗教','The historian used the term pagan for a worshipper of several local deities in the late Roman setting she was describing.','历史学家在所描述的晚期罗马背景中，用 pagan 指一位崇拜多位地方神祇的人。','The historian used the term pagan / for a worshipper of several local deities / in the late Roman setting / she was describing.','pagan.s1 指不属于主要宗教、或遵循被称为异教的信仰的人；历史语境需说明分类立场。','例句标出历史场景与具体多神信仰，避免笼统贴标签。','register'),M('The article called every person who follows a major world religion a pagan without explaining its historical or religious criteria.','The article used pagan for a specific historical group and explained the religious context of the label.','pagan 的分类具有历史语境，不应不加说明地套用于所有宗教信徒。','register'),[Q(1,'Whom did the historian call pagan in the passage?','A worshipper of several local deities in that historical setting.','Every person in every major religion.','A worker who packs rice.','pagan.s1 refers to a person associated with a religion labeled pagan.'),Q(1,'Which use of pagan is most careful?','A historian defines the term for a particular ancient religious context.','A writer applies it to everyone outside the writer’s own group.','A report uses it as a synonym for “evil.”','The first explains the label and its context.'),Q(1,'What is a pagan in the source sense?','A person following a belief system classified as pagan.','A person who never belongs to any community.','A person who refuses to read books.','The word names a religious adherent under that classification.'),Q(1,'Why should the label’s context be made clear?','Its use depends on historical and religious classification.','It always means “person from a city.”','It is the name of a rice field.','Careful context avoids treating a contested label as universal.','register')]);
P('paganism','From pagan + -ism; it names beliefs and rites of religions labeled pagan, especially pre-Christian or nature-based traditions.',C('paganism.s1','宗教','The course discussed local paganism through its seasonal rites and explained how the community itself described those practices.','课程通过季节性仪式讨论当地的异教信仰，并解释社群自身如何描述这些做法。','The course discussed local paganism / through its seasonal rites / and explained / how the community itself described those practices.','paganism.s1 指被称为 pagan 的宗教信仰与仪式，尤指前基督教或自然崇拜传统；使用标签时需说明语境。','例句提供具体仪式并尊重社群自称。','register'),M('The textbook defined paganism as a single uniform religion practiced identically by every society in history.','The textbook used paganism as a broad label for varied traditions and identified the specific community and rites discussed.','paganism 并非一种全球统一、所有社群相同的宗教。','meaning'),[Q(1,'What did the course examine about local paganism?','Seasonal rites and the community’s own descriptions.','A single worldwide ritual shared identically by all peoples.','A package of computer programs.','paganism.s1 concerns beliefs and rites in particular traditions.'),Q(1,'Which practice may be discussed under paganism in this source sense?','A pre-Christian seasonal rite tied to a nature tradition.','A method for sealing a parcel.','A medical oxygen treatment.','The source sense includes pre-Christian or nature-based religions.'),Q(1,'What does paganism name?','Beliefs and rites of religions classified as pagan.','One universal church with identical practices everywhere.','The act of walking quietly.','The noun refers to a broad class of religious traditions.'),Q(1,'How is paganism formed?','pagan + -ism','page + -er','paddy + -ish','-ism forms a noun for a belief system or practice.','word-formation')]);
P('page','The book-leaf noun comes from Latin pagina “written page,” through French; the web sense extends it to an online document, the verb means summon someone by pager/announcement, and the attendant noun has a separate history.',[C('page.s1','出版','She turned to the final page of the manual, where the safety instructions were printed in large type.','她翻到手册最后一页，那里用大号字体印着安全说明。','She turned to the final page / of the manual / where the safety instructions / were printed in large type.','page.s1 指书、信或文件纸张的一面。','手册的一面印有说明。'),C('page.s2','计算机','The library’s event page lists the time, room, and registration link for each public lecture.','图书馆的活动网页列出了每场公开讲座的时间、房间和报名链接。','The library’s event page / lists the time, room, / and registration link / for each public lecture.','page.s2 指万维网上的一个文档。','活动信息放在网页文档中。'),C('page.s3','通用','The nurse paged Dr. Chen over the hospital speaker system when the patient’s condition changed.','患者病情变化后，护士通过医院广播呼叫陈医生。','The nurse paged Dr. Chen / over the hospital speaker system / when the patient’s condition changed.','page.s3 作动词，指通过广播或传呼机召唤某人。','护士用广播叫医生前来。'),C('page.s4','历史','In the historical novel, a young page carried messages between the lord’s hall and the stable.','在这部历史小说里，一名年轻侍童在领主大厅和马厩之间传递消息。','In the historical novel / a young page carried messages / between the lord’s hall / and the stable.','page.s4 指旧时在旅馆或贵人身边服务的男孩。','侍童在贵人住所承担差事。')],M('The nurse paged the doctor by removing the call system and leaving no message or announcement.','The nurse paged the doctor by sending a call through the hospital speaker system.','page 作动词是通过呼叫系统召唤，不是取消呼叫。','meaning'),[Q(1,'Where were the safety instructions printed?','On the manual’s final page.','On a hospital loudspeaker.','On a medieval servant’s uniform.','page.s1 is one side of a printed document.'),Q(2,'What does the library event page contain?','Online details and a registration link.','A printed sheet only.','A message carried by a historical servant.','page.s2 is a web document.'),Q(3,'How did the nurse call Dr. Chen?','She paged him over the speaker system.','She turned to the last page of a book.','She sent him a software package.','page.s3 is the verb for summoning by pager or announcement.'),Q(4,'Who carried messages in the historical novel?','A young servant called a page.','A website document.','A hospital physician.','page.s4 is the old attendant sense.','distinction')]);
P('pageant','From Middle English pageant, originally a scene or play and later a public spectacle; today it often describes a colorful event with costumes or historical scenes.',C('pageant.s1','文化','The town staged a pageant about its harbor history, with residents in period costumes acting out the founding scenes.','小镇举办了一场介绍港口历史的盛会，居民穿着时代服装演绎建镇场景。','The town staged a pageant / about its harbor history / with residents in period costumes / acting out the founding scenes.','pageant.s1 指色彩丰富的公开表演，常有服装和历史场景。','演员穿历史服装重现当地往事。'),M('The town called a private meeting with no audience, costumes, or performance a public pageant.','The town staged a public pageant with costumes and historical scenes for residents.','没有表演或公众展示的私人会议不是 pageant。','meaning'),[Q(1,'What did the town’s pageant portray?','The harbor’s history.','A software package’s features.','A medical patient’s treatment.','pageant.s1 is a public spectacle, often showing historical scenes.'),Q(1,'Which event is a pageant?','A public procession with costumes and scenes from local history.','A closed budget meeting with no audience.','A quiet individual reading at home.','The first event is a colorful public spectacle.'),Q(1,'What feature often appears in a pageant?','Costumes and acted historical scenes.','A sealed package with no display.','A tax invoice only.','The source sense often includes costumes and historical scenes.'),Q(1,'Which word is closest in meaning to pageant here?','spectacle','receipt','apology','A pageant is a public spectacle or show.','meaning')]);
P('pail','From Middle English pail, likely borrowed from a North French form; the precise earlier derivation is uncertain. It means a bucket for carrying liquids or other things.',C('pail.s1','家居','She filled a metal pail with water and carried it to the garden to rinse the muddy tools.','她把水装进金属桶，提到花园里冲洗沾满泥土的工具。','She filled a metal pail with water / and carried it to the garden / to rinse / the muddy tools.','pail.s1 指盛液体或其他东西的桶。','金属桶用来装水并搬运。'),M('She poured the water into a pail made of paper that dissolved before she could carry it.','She poured the water into a sturdy metal pail and carried it outside.','易溶解的纸片不是能盛水搬运的桶。','meaning'),[Q(1,'What did she carry to the garden?','A metal bucket of water.','A packet of seeds.','A small paddle.','pail.s1 means a bucket.'),Q(1,'Which item is a pail?','A handled container for carrying water.','A flat sheet in a book.','A group of wolves.','A pail is a bucket for holding or carrying things.'),Q(1,'What did she rinse with the water?','Muddy tools.','A computer data packet.','The page of a manual.','The pail held water for cleaning the tools.'),Q(1,'Which container is suitable as a pail?','A sturdy bucket that can hold liquid.','A paper label that dissolves in water.','An open sheet with no sides.','A pail must be a bucket capable of holding things.','meaning')]);
P('pain','From Old French peine, from Latin poena “penalty, punishment”; it can mean bodily hurt, emotional distress, careful effort, or cause hurt as a verb.',[C('pain.s1','医学','The nurse asked the patient to rate the pain in her ankle after the fall.','护士询问患者跌倒后脚踝的疼痛程度。','The nurse asked the patient / to rate the pain / in her ankle / after the fall.','pain.s1 指受伤或疾病引起的身体疼痛。','疼痛位于脚踝并与跌倒有关。'),C('pain.s2','情感','He felt deep pain when his childhood friend moved away without saying goodbye.','儿时好友不辞而别搬走时，他感到深深的悲痛。','He felt deep pain / when his childhood friend moved away / without saying goodbye.','pain.s2 指强烈的不快乐或精神苦恼。','失去亲友带来情感痛苦。'),C('pain.s3','通用','She took great pains to check every figure in the grant application before submitting it.','提交资助申请前，她费了很大心力核对每一个数字。','She took great pains / to check every figure / in the grant application / before submitting it.','pain.s3 可指认真付出的辛苦和努力，常见于 take pains。','她仔细核查所有数字。'),C('pain.s4','书面','The memory of the unfair dismissal still pained him years later.','多年后，不公平解雇的回忆仍令他痛苦。','The memory of the unfair dismissal / still pained him / years later.','pain.s4 作动词，指使人身体或精神上难受。','回忆令他心里受伤。')],M('The patient reported no physical pain but the nurse recorded severe ankle pain after the fall.','The patient reported severe ankle pain after the fall.','报告没有疼痛与记录严重疼痛互相矛盾。','meaning'),[Q(1,'Where did the patient feel pain?','In her ankle.','In the application’s figures.','In a computer screen.','pain.s1 is physical hurt after an injury.'),Q(2,'What caused his deep pain?','His childhood friend moved away without goodbye.','He checked figures carefully.','His ankle was measured.','pain.s2 is emotional distress.'),Q(3,'What did she take great pains to do?','Check every figure carefully.','Leave the application unfinished.','Cause pain to a friend.','pain.s3 means careful effort in the phrase take pains.'),Q(4,'What still pained him years later?','The memory of an unfair dismissal.','A loose page in a book.','A loud overture.','pain.s4 is the verb meaning cause emotional hurt.','distinction')]);
P('painful','From pain + -ful; it describes something that causes physical hurt or is emotionally distressing.',C('painful.s1','健康','The painful cut stung when water touched it, so Mira covered it with a clean bandage.','伤口碰到水时很痛，米拉便用干净绷带包扎起来。','The painful cut stung / when water touched it / so Mira covered it / with a clean bandage.','painful.s1 指引起或让人感到身体或情绪疼痛的。','伤口遇水刺痛，体现身体疼痛。','word-formation'),M('The patient described the painless injection as painful even though she felt no discomfort during or after it.','The patient described the injection as painful because it caused a sharp sting.','完全没有不适的注射不符合“疼痛的”这一描述。','distinction'),[Q(1,'Why did Mira cover the cut?','It stung when water touched it.','It was a package needing a label.','It had already healed completely.','painful.s1 means causing physical pain.'),Q(1,'Which event may be painful emotionally?','Saying goodbye to a close friend who is moving far away.','Reading a neutral bus timetable.','Filling an empty pail with water.','A distressing farewell can cause emotional pain.'),Q(1,'What does painful describe?','Something that causes or involves pain.','Something impossible to see.','A person who owns a shop.','The adjective relates to physical or emotional hurt.'),Q(1,'Which suffix appears in painful?','-ful','-er','-ness','Painful is formed by adding -ful to pain.','word-formation')]);
P('painstaking','From the phrase take pains, meaning make a careful effort; painstaking describes work requiring or showing thorough care.',C('painstaking.s1','通用','The conservator made a painstaking record of each crack before restoring the old painting.','修复师在修复旧画前，细致记录了每一道裂纹。','The conservator made a painstaking record / of each crack / before restoring / the old painting.','painstaking.s1 指需要或体现非常仔细、彻底努力的。','逐一记录裂纹显示细致谨慎。','word-formation'),M('The technician made a painstaking inspection by glancing at the machine for one second and skipping every component.','The technician made a painstaking inspection by checking each component and recording every defect.','匆匆一瞥且遗漏部件不体现 painstaking 的细致。','distinction'),[Q(1,'What made the conservator’s record painstaking?','She documented each crack carefully.','She guessed the number of cracks.','She skipped the inspection.','painstaking.s1 describes thorough, careful effort.'),Q(1,'Which task is painstaking?','Comparing every line of a long manuscript for errors.','Glancing at a page once and closing the book.','Guessing the result without checking.','The first task requires sustained careful attention.'),Q(1,'What does painstaking mean?','Needing or showing very careful effort.','Causing a sudden physical injury.','Taking only a few seconds with no attention.','The adjective describes thorough care.'),Q(1,'What phrase is connected to the formation of painstaking?','take pains','make a pack','pay a pail','The word reflects taking pains to do something carefully.','word-formation')]);
P('paint','From Old French peindre, from Latin pingere “to paint”; as a noun it means coating or artist’s pigment, and as a verb it means make a picture, coat a surface, or describe in a certain way.',[C('paint.s1','通用','The painter chose exterior paint that could withstand rain and strong sunlight on the wooden door.','画家选了能经受雨水和强烈阳光的外墙涂料来刷木门。','The painter chose exterior paint / that could withstand rain / and strong sunlight / on the wooden door.','paint.s1 作名词，指干后在墙、木头或金属上形成色层的涂料。','涂料用于木门表面并能抵御天气。'),C('paint.s2','艺术','She mixed blue paint with a little white on the palette before working on the sky.','她在画天空前，把蓝色颜料和少量白色颜料在调色板上混合。','She mixed blue paint / with a little white / on the palette / before working on the sky.','paint.s2 作名词，指艺术家使用的颜料。','颜料在调色板上调色。'),C('paint.s3','艺术','At the weekend, Leo painted a watercolor of the harbor from the hill above town.','周末，利奥从镇上方的山坡上画了一幅港口水彩画。','At the weekend / Leo painted a watercolor of the harbor / from the hill / above town.','paint.s3 作动词，指用颜料创作图画。','他用颜料创作港口画作。'),C('paint.s4','通用','The maintenance team will paint the railings dark green after sanding away the loose coating.','维护团队会先磨掉松脱的涂层，再把栏杆刷成深绿色。','The maintenance team will paint the railings / dark green / after sanding away / the loose coating.','paint.s4 作动词，指把涂料涂到表面上。','栏杆被覆盖新涂层。'),C('paint.s5','写作','The article painted the delay as a minor inconvenience, although several patients missed urgent appointments.','文章把延误描绘成小小的不便，尽管好几位患者错过了紧急预约。','The article painted the delay / as a minor inconvenience / although several patients / missed urgent appointments.','paint.s5 作动词，可指以特定方式描绘或描述人、事。','文章对延误作了淡化描述。')],M('The article painted the delay as harmless even though patients missed urgent care, then described that language as a neutral factual account.','The article painted the delay as a minor inconvenience, a description that downplayed its serious effects.','把严重后果说成无害是带有立场的描绘，不是中性事实叙述。','distinction'),[Q(1,'Which paint did the team choose for the door?','A weather-resistant liquid coating.','Blue artist pigment on a palette.','A watercolor picture of the harbor.','paint.s1 is coating used on a surface.'),Q(3,'What did Leo do at the weekend?','He created a harbor picture with paint.','He coated metal railings.','He described a delay as harmless.','paint.s3 means make a picture using paint.'),Q(4,'What will the maintenance team do to the railings?','Cover them with dark-green paint.','Write an article about them.','Mix a watercolor of them.','paint.s4 means apply coating to a surface.'),Q(5,'How did the article paint the delay?','As a minor inconvenience.','As a colored surface.','As an artist’s palette.','paint.s5 means portray or describe in a particular way.','distinction')]);
P('painter','From paint + -er; it names someone who creates pictures with paint or applies paint to surfaces as a trade.',[C('painter.s1','艺术','The painter displayed a landscape she had made with oil paints at the community gallery.','这位画家在社区画廊展出了自己用油彩创作的风景画。','The painter displayed a landscape / she had made / with oil paints / at the community gallery.','painter.s1 指用颜料创作画作的人，也可指以涂刷表面为业的人。','油彩风景画表明这里的 painter 是画家。'),C('painter.s1','工作','The building painter covered the floors before applying a fresh coat to the classroom walls.','建筑油漆工在给教室墙面刷新漆前，先把地板遮盖起来。','The building painter covered the floors / before applying a fresh coat / to the classroom walls.','painter.s1 也可指以粉刷墙面或建筑为业的人。','给墙壁涂漆体现职业油漆工的工作。')],M('The building painter damaged the classroom walls by leaving them bare, yet the manager praised the fresh coat of paint he had applied.','The building painter applied a fresh coat to the classroom walls.','墙面仍然裸露就不能说工人刷了新漆。','meaning'),[Q(1,'What did the gallery painter display?','An oil-painted landscape.','A freshly painted classroom wall.','A network data packet.','painter.s1 includes an artist who creates pictures.'),Q(1,'What did the building painter do?','Covered the floor and painted the walls.','Displayed a landscape in a gallery.','Repaired the roof tiles.','The context uses painter for a tradesperson who applies paint.'),Q(1,'Who can be called a painter?','An artist who makes pictures with paint.','Only someone who sells paint but never uses it.','A person who writes a page of text.','The word includes a person who creates pictures.'),Q(1,'Which painter works as a trade on building surfaces?','A decorator who applies paint to walls.','A museum visitor looking at a picture.','A courier delivering a package.','The second context shows the surface-painting trade.','distinction')]);
P('painting','From paint + -ing; it means either a picture made with paint or the activity/skill of making such pictures.',[C('painting.s1','艺术','The small painting of the harbor hung above the desk, with blue-gray water and a red fishing boat.','这幅小港口画挂在书桌上方，画中有蓝灰色海水和一艘红色渔船。','The small painting of the harbor / hung above the desk / with blue-gray water / and a red fishing boat.','painting.s1 指用颜料创作的画作。','painting 是挂在墙上的成品画。'),C('painting.s2','艺术','After retirement, Luis took up painting and practiced mixing colors at the studio each morning.','退休后，路易斯开始绘画，每天早上都在工作室练习调色。','After retirement / Luis took up painting / and practiced mixing colors / at the studio each morning.','painting.s2 指用颜料作画的活动或技巧。','练习调色和作画是绘画活动。')],M('Luis took up painting by never using colors or making any pictures, then called the activity painting.','Luis took up painting by practicing how to make pictures with color.','完全不作画就不是从事绘画活动。','meaning'),[Q(1,'What hung above the desk?','A picture of the harbor.','A jar of blue paint.','A page from a manual.','painting.s1 names a picture made with paint.'),Q(2,'What did Luis practice at the studio?','The activity of making pictures with paint.','Packing a suitcase.','Paddling a canoe.','painting.s2 is the activity or skill.'),Q(1,'Which is a painting?','A finished canvas showing a landscape.','The act of cleaning a brush only.','A bottle of wall coating.','The finished picture is a painting.'),Q(2,'Which phrase refers to the activity?','She studied painting for two years.','The painting hangs in the hall.','A painting was sold at auction.','The first example names the practice or skill.','distinction')]);
P('pair','From Old French paire, from Latin par “equal”; pair means two things used together, two people together, or the verb that puts two together.',[C('pair.s1','通用','He bought a pair of gloves because the cold weather made it difficult to work with bare hands.','天气寒冷，光着手工作不方便，所以他买了一双手套。','He bought a pair of gloves / because the cold weather / made it difficult / to work with bare hands.','pair.s1 指一起使用的两个同类物品。','两只手套作为一双使用。'),C('pair.s2','社交','The pair of volunteers worked together to guide visitors through the crowded gallery.','这两位志愿者一起工作，引导参观者穿过拥挤的展厅。','The pair of volunteers / worked together / to guide visitors / through the crowded gallery.','pair.s2 指一起做事的两个人，也可指一对伴侣。','两人搭档共同引导游客。'),C('pair.s3','通用','The teacher paired each new student with a classmate who could show them around.','老师把每位新生分别安排与一名同学搭档，由对方带他们熟悉校园。','The teacher paired each new student / with a classmate / who could show them / around.','pair.s3 作动词，指把两个人或物配在一起。','老师把新生与同学配对。')],M('The teacher paired each new student with three unrelated partners and said each student had been paired with one classmate.','The teacher paired each new student with one classmate.','pair 表示组成一对，不能把三名伙伴说成一对。','number'),[Q(1,'Why did he buy a pair of gloves?','He needed two gloves to use together.','He needed one shoe.','He wanted a single painting.','pair.s1 means two matching or related items.'),Q(2,'What did the pair of volunteers do?','They worked together to guide visitors.','They worked separately in different cities.','They painted one glove.','pair.s2 describes two people acting together.'),Q(3,'How did the teacher pair students?','She matched each new student with one classmate.','She assigned every student three partners.','She left all new students alone.','pair.s3 means put two people together.'),Q(1,'Which item is commonly bought as a pair?','A pair of shoes.','A single pail.','A pack of wolves.','Shoes are two related items used together.','collocation')]);
P('paired','From pair + -ed; it describes two people or things placed or working together as a pair.',C('paired.s1','通用','The paired sensors monitored the same bridge from opposite ends so engineers could compare their readings.','成对的传感器从桥的两端监测同一座桥，便于工程师比较读数。','The paired sensors / monitored the same bridge / from opposite ends / so engineers could compare their readings.','paired.s1 指被成对安排或协同工作的。','两个传感器作为一组工作。','word-formation'),M('The sensors were described as paired even though one was removed and the other operated alone.','The sensors were paired because both operated together on the same bridge.','单独运行的一个传感器不是与另一个成对工作。','meaning'),[Q(1,'Why were the sensors paired?','They worked together to monitor one bridge.','They were installed in unrelated countries.','They belonged to different projects with no connection.','paired.s1 means arranged or working as a pair.'),Q(1,'Which items are paired?','Two matched keys attached to one label.','One key with no partner.','A crowd of unrelated objects.','The two matched keys form a pair.'),Q(1,'What does paired mean here?','Placed or working together as a pair.','Used only once and thrown away.','Working against one another.','The adjective describes a pair arrangement.'),Q(1,'Which verb is paired based on?','pair','pale','pain','Paired is the past participle/adjective formed from pair.','word-formation')]);
P('pajamas','From Hindi pāyjāma “leg garment,” from Persian pāy “leg” + jāma “clothing”; pajamas are nightclothes consisting of a top and trousers.',C('pajamas.s1','日常','She folded her cotton pajamas and put the matching top and trousers in the overnight bag.','她叠好棉质睡衣，把配套上衣和裤子放进过夜包。','She folded her cotton pajamas / and put the matching top and trousers / in the overnight bag.','pajamas.s1 指由上衣和裤子组成的睡衣。','上下两件配套衣物构成一套睡衣。','word-formation'),M('She packed a nightdress and a winter coat but said she had packed a top-and-trousers set of pajamas.','She packed a matching pajama top and trousers for sleeping.','只有睡裙和外套并非题述的上下两件式 pajamas。','meaning'),[Q(1,'What did she pack as pajamas?','A matching top and trousers for sleeping.','A daytime business suit.','A single raincoat.','pajamas.s1 is nightclothes consisting of a top and trousers.'),Q(1,'Which clothes are pajamas?','A loose sleeping top with matching trousers.','A pair of boots for hiking.','A one-piece formal gown only.','The first is the two-piece sleepwear described.'),Q(1,'What does the etymological element pāy mean?','Leg or foot.','Night sky.','Cotton cloth only.','The Persian source pāy means leg or foot.'),Q(1,'Why does the word’s history connect to trousers?','The source term referred to a leg garment.','It originally named a palace.','It referred to a river crossing.','Pāyjāma was a garment for the legs.','word-formation')]);
P('pal','From Anglo-Romani pal “brother, friend”; an informal word for a friend or companion.',C('pal.s1','社交','Mara invited her old pal from college to join the neighborhood picnic.','玛拉邀请大学时的老朋友参加社区野餐。','Mara invited her old pal / from college / to join / the neighborhood picnic.','pal.s1 是非正式说法，指朋友或伙伴。','old pal 指相识已久的朋友。','register'),M('Mara called a stranger she had never met her lifelong pal and said they had shared years of friendship.','Mara called the longtime friend she had known for years her pal.','初次见面的陌生人不是相识多年的老朋友。','meaning'),[Q(1,'Whom did Mara invite?','An old friend from college.','A stranger she had never met.','A palace guard.','pal.s1 is an informal word for a friend.'),Q(1,'Which sentence uses pal naturally?','I met my pal for lunch after work.','The legal pal confirmed ownership of the house.','The pal absorbed ultraviolet radiation.','The first uses pal as a casual synonym for friend.'),Q(1,'What is the tone of pal?','Informal and friendly.','Highly technical and scientific.','A formal legal title.','Pal is mainly used informally.'),Q(1,'Which word is closest in meaning to pal?','friend','rival','stranger','A pal is a friend or companion.','meaning')]);
P('palace','From Old French palais, from Latin palatium, the name of the imperial residence on Rome’s Palatine Hill; it means a ruler’s official home or a very large splendid house.',[C('palace.s1','建筑','The royal palace opened its east wing to visitors after the restoration was completed.','修复完成后，王宫向游客开放了东翼。','The royal palace / opened its east wing / to visitors / after the restoration was completed.','palace.s1 指国王、女王、总统等统治者的官邸。','royal palace 是王室正式住所。'),C('palace.s2','通用','The retired architect built a glass-and-stone palace on the hill, with more rooms than his family could use.','退休建筑师在山上建了一座玻璃与石材打造的豪宅，房间多到全家用不完。','The retired architect built / a glass-and-stone palace / on the hill / with more rooms than his family could use.','palace.s2 可指非常大而华丽的住宅。','句中 palace 是夸张地形容私人豪宅。')],M('The village called its single-room shed a palace although it was neither a ruler’s residence nor a large, splendid house.','The village called the grand, many-room residence a palace.','简陋小棚不符合王宫或豪华巨宅的含义。','meaning'),[Q(1,'What opened to visitors after restoration?','The royal ruler’s residence.','The architect’s small garden shed.','A packet of software.','palace.s1 is an official home of a ruler.'),Q(2,'Why was the architect’s home called a palace?','It was a very large and splendid house.','It belonged to a king.','It was a small one-room shed.','palace.s2 can be an impressive private house.'),Q(1,'Which building is a palace in the official sense?','A monarch’s formal residence.','A public bus shelter.','A small storage closet.','A palace can be a ruler’s official home.'),Q(2,'Which private home might be called a palace?','A vast, luxurious mansion.','A narrow tent with one bed.','A plain garden tool shed.','The term can be used for a very large, splendid house.','meaning')]);
P('palatable','From palate + -able; it means pleasant to taste, or figuratively acceptable and easy to accept.',[C('palatable.s1','饮食','The chef added lemon and herbs to make the low-salt soup more palatable without adding much sodium.','厨师加入柠檬和香草，让低盐汤更可口，同时没有增加多少钠。','The chef added lemon and herbs / to make the low-salt soup / more palatable / without adding much sodium.','palatable.s1 指味道令人愉快、可口的。','调味让汤更好入口。'),C('palatable.s2','通用','The mediator proposed a compromise that made the new schedule more palatable to both teams.','调解员提出了一项折中方案，让新日程更容易被两支队伍接受。','The mediator proposed a compromise / that made the new schedule / more palatable / to both teams.','palatable.s2 比喻指容易接受或认可的。','折中方案让双方都更愿意接受安排。')],M('The chef made the soup more palatable by making it bitter and unpleasant to taste.','The chef made the soup more palatable by balancing its flavors with herbs and lemon.','令人难以入口的苦味不会使汤更可口。','meaning'),[Q(1,'How did the chef make the soup palatable?','By balancing flavors with lemon and herbs.','By making it bitter and unpleasant.','By removing all liquid.','palatable.s1 means pleasant to taste.'),Q(2,'Why was the compromise palatable to both teams?','Each team could accept the new schedule.','Both teams rejected it immediately.','It was served as a meal.','palatable.s2 means acceptable in a figurative sense.'),Q(1,'Which food is palatable?','A well-seasoned soup with a pleasant taste.','A dish that tastes spoiled and bitter.','A meal no one can safely eat.','The first food is pleasant to taste.'),Q(2,'Which proposal is more palatable?','A fair compromise both sides can accept.','A demand that both sides refuse.','A schedule with no consultation.','Figurative palatable means acceptable.','distinction')]);
P('palate','From Latin palatum “roof of the mouth”; palate names the physical roof of the mouth and, figuratively, a person’s ability to judge flavors or preferences.',[C('palate.s1','医学','The dentist examined the roof of the child’s mouth and found a small sore on the palate.','牙医检查了孩子的口腔顶部，在上腭发现一处小溃疡。','The dentist examined / the roof of the child’s mouth / and found a small sore / on the palate.','palate.s1 指口腔顶部的骨性和软组织部分。','检查部位是口腔顶部。'),C('palate.s2','饮食','Her trained palate noticed the subtle difference between the two olive oils.','她受过训练的味觉尝出了两种橄榄油之间的细微差别。','Her trained palate / noticed the subtle difference / between the two olive oils.','palate.s2 指辨别风味的能力，也可指食物或艺术品味。','她能分辨油的细微味道差异。')],M('The dentist examined the palate by looking at the roof of the child’s foot.','The dentist examined the palate by looking at the roof of the child’s mouth.','palate 指口腔顶部，不是脚底。','confusable'),[Q(1,'Where did the dentist find the sore?','On the roof of the child’s mouth.','On the sole of the child’s foot.','On the outside of the dentist’s glove.','palate.s1 is the roof of the mouth.'),Q(2,'What did her trained palate detect?','A subtle flavor difference between oils.','A sore on the roof of the mouth.','A difference in the page layout.','palate.s2 is the ability to judge flavors.'),Q(1,'Which body part is the palate?','The roof of the mouth.','The roof of the nose.','The underside of the foot.','The physical palate is inside the mouth.'),Q(2,'Which person has a discerning palate?','A taster who notices subtle flavors.','A dentist who only checks spelling.','A diner who cannot taste differences.','Palate can mean flavor-judging ability.','meaning')]);
P('pale','From Old French pale, from Latin pallidus “pallid”; as an adjective it means unusually light-faced or light in color, and as a verb it means become pale or seem less important by comparison.',[C('pale.s1','通用','After the long fever, his face looked pale and tired, so the nurse checked his temperature.','长时间发烧后，他脸色苍白、显得疲惫，护士便给他量了体温。','After the long fever / his face looked pale and tired / so the nurse / checked his temperature.','pale.s1 指因疾病、恐惧或震惊而脸色比平时苍白。','苍白的脸色促使护士检查病情。'),C('pale.s2','色彩','They painted the bedroom a pale green that kept the small room bright without looking vivid.','他们把卧室刷成浅绿色，让小房间保持明亮而不显得鲜艳。','They painted the bedroom / a pale green / that kept the small room bright / without looking vivid.','pale.s2 指颜色浅、不浓不深。','浅绿色不鲜艳、色调较淡。'),C('pale.s3','书面','The new phone’s battery life paled beside the older model, which lasted almost twice as long.','新手机的续航能力与旧款相比相形见绌，旧款几乎能用两倍时间。','The new phone’s battery life / paled beside the older model / which lasted / almost twice as long.','pale.s3 作动词，指与另一事物相比显得逊色。','新款续航不如旧款。'),C('pale.s4','书面','Her face paled when the alarm sounded, and she reached for the emergency phone.','警报响起时，她脸色一下变白，伸手去拿紧急电话。','Her face paled / when the alarm sounded / and she reached for / the emergency phone.','pale.s4 作动词，指脸色变得苍白。','警报使她受惊而脸色发白。')],M('The editor wrote that the newcomer’s performance paled beside the star’s even though the newcomer was far more impressive in every respect.','The editor wrote that the newcomer’s performance outshone the star’s in every respect.','若表现更出色，就不能说它 paled beside 对方。','distinction'),[Q(1,'Why did the nurse check his temperature?','His face looked unusually pale after a fever.','The room had pale-green walls.','His phone battery lasted twice as long.','pale.s1 describes an unusually light face from illness.'),Q(2,'What color were the bedroom walls?','A light green shade.','A vivid dark green.','A completely colorless clear coating.','pale.s2 means light rather than strong or dark in color.'),Q(3,'How did the new phone compare with the older model?','Its battery life seemed inferior.','It lasted twice as long.','It changed color in sunlight.','pale.s3 means seem less impressive by comparison.'),Q(4,'What happened when the alarm sounded?','Her face became pale.','The bedroom became green.','The phone gained battery life.','pale.s4 is the verb meaning become pale.','distinction')]);
P('paleoanthropologist','From paleo- “ancient” + anthropology + -ist; it names a researcher of fossil hominins and early human evolution.',C('paleoanthropologist.s1','科学','The paleoanthropologist compared fossil jaw fragments from two sites to study changes in early hominin diets.','古人类学家比较了两个遗址的颌骨化石碎片，以研究早期人科的饮食变化。','The paleoanthropologist compared fossil jaw fragments / from two sites / to study changes / in early hominin diets.','paleoanthropologist.s1 指研究人科化石与早期人类演化的学者。','颌骨化石用于研究早期人科。','word-formation'),M('The paleoanthropologist studied only modern bird feathers and made no research on fossil hominins or human evolution.','The paleoanthropologist studied fossil hominins to understand early human evolution.','只研究现代鸟羽不属于古人类学的研究对象。','meaning'),[Q(1,'What did the researcher compare?','Fossil jaw fragments from two sites.','Modern bird feathers only.','A set of palace floor plans.','paleoanthropologist.s1 studies fossil hominins and early humans.'),Q(1,'Which question might a paleoanthropologist investigate?','How early hominin skulls changed over time.','How current phone batteries are designed.','How to package a shipment.','The first concerns early human evolution.'),Q(1,'What is the paleoanthropologist’s research focus?','Fossil hominins and early human evolution.','All modern insects only.','The legal ownership of a fossil collection.','The term names a specialist in human ancestors.'),Q(1,'What does paleo- mean in paleoanthropologist?','Ancient.','Peaceful.','Painful.','The prefix paleo- refers to the ancient past.','word-formation')]);
P('paleoecologist','From paleo- “ancient” + ecology + -ist; it names someone who reconstructs past environments from fossils, sediments, and other evidence.',C('paleoecologist.s1','科学','The paleoecologist studied pollen preserved in lake sediment to reconstruct the forest that grew there thousands of years ago.','古生态学家研究湖泊沉积物中保存的花粉，以重建数千年前生长在那里的森林。','The paleoecologist studied pollen / preserved in lake sediment / to reconstruct the forest / that grew there thousands of years ago.','paleoecologist.s1 指依据化石与沉积物重建古代环境的研究者。','花粉和沉积物提供过去生态环境证据。','word-formation'),M('The paleoecologist reconstructed an ancient wetland using only a current restaurant menu and no environmental evidence.','The paleoecologist reconstructed the ancient wetland from pollen and sediment evidence.','没有古环境证据的菜单无法支撑古生态重建。','context'),[Q(1,'What evidence did the paleoecologist study?','Pollen preserved in lake sediment.','A current restaurant menu.','A new software package.','paleoecologist.s1 uses fossils or sediments to infer past environments.'),Q(1,'Which project belongs to a paleoecologist?','Reconstructing an ancient forest from fossil pollen.','Painting a modern landscape.','Measuring current phone battery life.','The first project studies past ecological conditions.'),Q(1,'What does a paleoecologist reconstruct?','Ancient environments.','Only the biographies of kings.','The packaging design of a product.','The word names a researcher of past ecosystems.'),Q(1,'Which two parts help build paleoecologist?','paleo- + ecology + -ist','pale + -ful + -ness','palace + -er','The word combines ancient, ecology, and a person suffix.','word-formation')]);
P('Paleolithic','From Greek palaios “old” + lithos “stone”; Paleolithic describes the earliest part of the Stone Age.',C('Paleolithic.s1','历史','The museum displayed Paleolithic stone tools found near a cave used by early human communities.','博物馆展出了在早期人类社群使用的洞穴附近发现的旧石器时代工具。','The museum displayed Paleolithic stone tools / found near a cave / used by early human communities.','Paleolithic.s1 指属于石器时代最早阶段的。','石制工具与早期人类时代相联系。','word-formation'),M('The curator labeled a newly manufactured steel wrench Paleolithic even though it was made this year.','The curator labeled the ancient chipped-stone tool Paleolithic.','今年制造的钢制工具不属于旧石器时代。','meaning'),[Q(1,'What did the museum display?','Ancient stone tools from an early human site.','A new steel wrench made this year.','A modern software package.','Paleolithic.s1 means belonging to the earliest Stone Age.'),Q(1,'Which object is Paleolithic?','A chipped stone tool from deep prehistory.','A steel screwdriver from a recent factory.','A paper page from a current manual.','The first object belongs to the earliest Stone Age.'),Q(1,'What does lithic contribute to Paleolithic?','Stone.','Friendship.','Oxygen.','The Greek root lithos means stone.'),Q(1,'What period does Paleolithic describe?','The earliest part of the Stone Age.','The modern industrial era.','A future geological age.','Paleolithic refers to the earliest Stone Age period.','meaning')]);
P('paleontologist','From paleontology + -ist; paleontology combines Greek palaios “ancient,” ontos “being,” and -logia “study”; a paleontologist studies fossils of organisms.',C('paleontologist.s1','科学','The paleontologist identified a fossil fern beside the dinosaur bones and explained what it revealed about the ancient habitat.','古生物学家在恐龙骨骼旁辨认出一块蕨类化石，并解释它揭示了古代栖息环境的什么信息。','The paleontologist identified a fossil fern / beside the dinosaur bones / and explained / what it revealed about the ancient habitat.','paleontologist.s1 指研究动物、植物及其他生物化石的学者。','植物化石与恐龙骨骼都属于古生物研究材料。','word-formation'),M('The paleontologist described the fossil fern as a living plant collected this morning rather than a preserved ancient organism.','The paleontologist described the fern impression in rock as a plant fossil.','岩石中的蕨类印痕是化石，不是今早采集的活植物。','meaning'),[Q(1,'What fossil did the paleontologist identify?','A fern impression beside dinosaur bones.','A living fern picked that morning.','A package label.','paleontologist.s1 studies fossils of organisms.'),Q(1,'Which question might a paleontologist answer?','What ancient animals and plants lived in this region?','How can a person make a sleeping garment?','Which team signed a pact?','The first concerns fossil organisms.'),Q(1,'What is broader about paleontologist compared with paleoanthropologist?','It can study fossils of many organisms, not only hominins.','It studies only human language.','It studies only current weather.','Paleontology covers fossil animals, plants, and other organisms.'),Q(1,'What does -logist commonly name?','A person who studies a subject.','A thing that is being packed.','A person who owns a palace.','The suffix -logist names a specialist or scholar.','word-formation')]);

})();
